/*
 * 地理総合・地理探究のテキスト本文(このアプリのオリジナル)。書式は lessons_1.js 冒頭のコメントと同じ。
 * 統計の数値は年によって変わるので、確実な順位や傾向だけを書いている。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ---------- 図 ----------
  var ROUTE = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="メルカトル図法の地図上で、2地点を結ぶ等角航路は直線、大圏航路は北へふくらむ曲線になる"><rect x="10" y="10" width="200" height="100" class="bx"/><line x1="10" y1="35" x2="210" y2="35" class="dash"/><line x1="10" y1="60" x2="210" y2="60" class="dash"/><line x1="10" y1="85" x2="210" y2="85" class="dash"/><line x1="40" y1="80" x2="180" y2="80" class="cv"/><path d="M40 80 Q110 18 180 80" class="cv2"/><circle cx="40" cy="80" r="4" class="pt"/><circle cx="180" cy="80" r="4" class="pt"/><text x="28" y="100">A</text><text x="176" y="100">B</text><text x="70" y="96">等角航路(直線)</text><text x="62" y="44">大圏航路(最短)</text><text x="14" y="22">北(高緯度)</text><text x="20" y="132">最短コースは曲線に見える</text></svg>';
  var CIRC = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="北半球の気圧帯と風。赤道低圧帯、亜熱帯高圧帯、亜寒帯低圧帯、極高圧帯と、その間をふく貿易風・偏西風・極東風"><line x1="40" y1="12" x2="205" y2="12" class="ax"/><line x1="40" y1="50" x2="205" y2="50" class="ax"/><line x1="40" y1="90" x2="205" y2="90" class="ax"/><line x1="40" y1="130" x2="205" y2="130" class="ax"/><text x="8" y="16">90°</text><text x="8" y="54">60°</text><text x="8" y="94">30°</text><text x="14" y="134">0°</text><text x="46" y="26">極高圧帯</text><text x="46" y="46">亜寒帯低圧帯</text><text x="46" y="86">亜熱帯高圧帯</text><text x="46" y="126">赤道低圧帯</text><text x="132" y="34">極東風 ←</text><text x="132" y="74">偏西風 →</text><text x="132" y="114">貿易風 ←</text><path d="M125 20 Q120 31 125 42" class="arc"/><path d="M125 58 Q120 70 125 82" class="arc"/><path d="M125 98 Q120 110 125 122" class="arc"/></svg>';

  // ===== 地図の図法・時差・GIS =====
  L.gg_map = {
    goal: '目的に合った地図の図法と統計地図を選べ、時差を正しく計算でき、GIS(地理情報システム)が何に役立つかを説明できるようになる。',
    intro: '丸いミカンの皮をむいて、机の上に平らに広げてみてください。どうやっても、どこかが破れたり、のびたりします。地球も同じで、球の表面を平らな紙にかくと、【面積・形・距離・方位】のどれかが必ずゆがみます。だから地図には、目的に合わせて「何を正しくするか」を選んだいろいろな【図法】があります。この単元では、図法の選び方、時差の計算、そしてデータを重ねて見る【GIS】を学びます。',
    pre: '【緯度】は赤道を0度として南北に90度まで、【経度】はイギリスのロンドン(旧グリニッジ天文台)を通る【本初子午線】を0度として東西に180度まで測ります。同じ緯度を結んだ線が緯線、同じ経度を結んだ線が経線です。\n地球は24時間で1回転(360度)するので、経度15度ごとに1時間の時差が生まれます。日本の標準時は【東経135度】(兵庫県明石市を通る経線)を基準にしています。\n中学では、縮尺(実際の距離を地図上で何分の1に縮めたか)と、地形図の読み方も学びました。2万5千分の1の地形図では、地図上の1cmが実際の250mにあたります。等高線は、主曲線が10mごと、計曲線が50mごとに引かれます。\n地図には、地形や道路などを広くのせた【一般図】(地形図など)と、テーマをしぼって表した【主題図】(人口の分布図、土地利用図など)があります。この単元では主に主題図の表し方を学びます。',
    secs: [
      { h: '地図はかならずゆがむ:何を正しくするかで選ぶ', t: 'なぜ地図はゆがむのでしょうか。球の表面は平面に切り開くことができないからです。面積・形(角度)・距離・方位の4つを、1枚の平面地図ですべて正しく表すことはできません。\nそこで、目的に合わせて「何を正しくするか」を決めて地図をかきます。この決め方を【図法】(投影法)といいます。\n大きく分けると、角度が正しい【正角図法】、面積が正しい【正積図法】、特定の点からの距離が正しい【正距図法】、特定の点からの方位が正しい【方位図法】があります。\nどれか1つを正しくすると、ほかの性質がくずれます。たとえば面積を正しくすると、周辺部で形がゆがみます。\nだから地図を読むときは、まず「この地図は何が正しい図法か」を確かめることが大切です。面積の比較を、面積の正しくない地図で行うとまちがえてしまいます。',
        key: '地図は必ずどこかがゆがむ。目的(何を比べたいか)に合わせて、正しく表す性質を選ぶ。' },
      { h: '代表的な図法:メルカトル・正距方位・正積図法', t: '【メルカトル図法】は、経線と緯線がどこでも直角に交わる正角図法です。地図上で2点を結んだ直線は、経線と常に同じ角度で交わるコース(【等角航路】)になります。羅針盤(コンパス)の向きを一定にして進めばよいので、昔から【海図】に使われてきました。\nその代わり、高緯度ほど面積や距離が大きく引きのばされます。緯度60度では、東西の長さが赤道付近の約2倍に表されます。グリーンランドが実際よりずっと大きく見えるのはこのためです。また、極(北極・南極)は表せません。\n【正距方位図法】は、図の中心からの【距離と方位】が正しい図法です。中心と任意の地点を結んだ直線が、2点間の最短コース(【大圏航路】)になります。航空機のルートを考えるのに便利で、航空図に使われます。図の外周は、中心の真裏の地点(対蹠点)を表します。ただし、中心以外の2地点間の距離や方位は正しくありません。\n【モルワイデ図法】や【サンソン図法】は、面積が正しい正積図法で、人口や作物の分布など「どこにどれだけあるか」を表す分布図に向いています。サンソン図法は低緯度、モルワイデ図法は高緯度のゆがみが比較的小さいので、両者を緯度40度あたりでつないだのが【グード図法】(ホモロサイン図法)です。海洋の部分を切って大陸の形のゆがみを小さくしています。',
        key: 'メルカトル=角度が正しい(等角航路が直線・海図)。正距方位=中心からの距離と方位が正しい(大圏航路が直線・航空図)。モルワイデ・サンソン・グード=面積が正しい(分布図)。',
        fig: ROUTE,
        ex: [
          { q: '東京からサンフランシスコへ飛行機で向かう最短コースを、メルカトル図法の地図にかくと、直線・北へふくらむ曲線・南へふくらむ曲線のどれになる?', hint: '最短コースは大圏航路です。メルカトル図法は高緯度ほど東西に引きのばされます。', steps: ['地球上の2点間の最短コースは、地球の中心を通る平面で地球を切った切り口(大円)にそった【大圏航路】である。', '北半球の2地点を結ぶ大圏航路は、地球儀上で北(高緯度)の側を通る。', 'メルカトル図法では高緯度ほど東西に引きのばされるので、高緯度を通るコースは長くのびて見える。', 'そのため大圏航路は、直線(等角航路)より北へふくらんだ曲線としてえがかれる。'], a: '北へふくらむ曲線', check: '地球儀の上で東京とサンフランシスコに糸を張ると、糸がアリューシャン列島近くの北の方を通ることで確かめられます。' }
        ] },
      { h: '時差の計算', t: 'なぜ時差が生まれるのでしょうか。地球が西から東へ自転しているので、東にある地点ほど先に太陽がのぼり、時刻が進んでいるからです。\nやり方は3段階です。(1)2地点の【経度差】を求める。東経どうし・西経どうしなら引き算、東経と西経なら足し算。(2)経度差を15でわって時差を出す。(3)東にある方が進んでいるので、西にある地点の時刻は時差の分だけもどす。\n各国は基準にする経線(【標準時子午線】)を決めています。イギリスは経度0度、日本は東経135度です。アメリカやロシアのように東西に広い国は、国内に複数の標準時があります。\nほぼ180度の経線にそって【日付変更線】が引かれています。これを西から東へこえるときは日付を1日おくらせ、東から西へこえるときは1日進めます。\n飛行機の到着時刻の問題では、「出発地の時刻+飛行時間」をまず出発地の時刻で計算し、最後に到着地の時刻に直すと迷いません。なお、夏の時刻を1時間進める【サマータイム】を行う国もありますが、問題文に指示がなければ考えません。',
        key: '経度差÷15=時差。東の方が時刻が進んでいる。東経と西経の間は経度を足す。',
        ex: [
          { q: '東京が1月1日午前10時のとき、ニューヨーク(西経75度の標準時)は何月何日の何時?', hint: '東経135度と西経75度は本初子午線をはさんでいます。', steps: ['東経と西経なので経度差は足し算:135+75=210度。', '時差は210÷15=14時間。', 'ニューヨークは東京より西(日付変更線をまたがずに比べると西側)なので、14時間おくれている。', '1月1日午前10時から14時間もどすと、12月31日午後8時。'], a: '12月31日午後8時', check: 'ニューヨークの12月31日午後8時に14時間を足すと、1月1日午前10時にもどります。' },
          { q: '成田を1月10日午後6時(日本時間)に出発し、10時間かけてロンドン(経度0度)に着いた。到着は現地時間で何日の何時?(サマータイムは考えない)', hint: 'まず日本時間で到着時刻を出し、そのあとでロンドンの時刻に直します。', steps: ['日本時間で到着時刻を出す:1月10日午後6時+10時間=1月11日午前4時(日本時間)。', '日本とロンドンの時差は135÷15=9時間で、ロンドンの方が9時間おくれている。', '1月11日午前4時から9時間もどすと、1月10日午後7時。'], a: '1月10日午後7時(現地時間)', check: '出発時の日本時間午後6時はロンドンでは午前9時なので、そこから10時間後は午後7時となり、一致します。' }
        ] },
      { h: '統計地図:絶対値か相対値かで選ぶ', t: 'テーマをしぼって数値を表す主題図を【統計地図】といいます。どの表し方を選ぶかは、表したい数値が【絶対値】(人口・生産量など、そのままの量)か、【相対値】(人口密度・割合など、比べるために計算した値)かで決まります。\n【階級区分図】は、地域ごとに数値をいくつかの階級に分け、色や模様の濃さで表します。人口密度・高齢者の割合など相対値に向いています。人口のような絶対値を塗り分けると、面積の広い地域が目立ってしまい、誤解をまねきます。\n【図形表現図】は、円や棒の大きさで数値を表し、生産量など絶対値に向いています。【ドットマップ】は、1つの点で一定量(例:1点=1万人)を表し、分布のようすを示します。\n【等値線図】は、気温や降水量のように連続して変わる値の等しい地点を線で結んだ地図です。【流線図】は、人や物の移動の方向と量を矢印の向きと太さで表します。\n【カルトグラム】は、数値の大きさに合わせて地域の面積や形そのものを変形させた地図です。人口の大きい国が大きく見えるので、量の差が直感的に分かります。',
        key: '相対値(密度・割合)は階級区分図、絶対値(量)は図形表現図やドットマップ。移動は流線図、連続する値は等値線図。',
        flow: { title: '統計地図の選び方', cols: 3, head: ['地図', '表すもの', '例'], rows: [
          [['階級区分図', 'b'], ['相対値', 'b', 1, '色の濃さ'], ['人口密度・高齢化率', 'b']],
          [['図形表現図', 'g'], ['絶対値', 'g', 1, '円や棒の大きさ'], ['米の生産量', 'g']],
          [['ドットマップ', 'g'], ['絶対値の分布', 'g', 1, '1点=一定量'], ['家畜の分布', 'g']],
          [['等値線図', 'o'], ['連続する値', 'o', 1, '同じ値を線で結ぶ'], ['気温・降水量', 'o']],
          [['流線図', 'r'], ['移動の向きと量', 'r', 1, '矢印の太さ'], ['人口移動・貿易', 'r']]
        ], legend: [['b', '相対値'], ['g', '絶対値'], ['o', '連続する値'], ['r', '移動']] },
        ex: [{ q: '都道府県別の「人口」と「人口密度」を地図に表したい。それぞれに適した統計地図は?', hint: '人口は絶対値、人口密度は相対値です。', steps: ['人口はそのままの量なので【絶対値】、人口密度は人口を面積でわった【相対値】である。', '絶対値は、円の大きさなどで量を表す図形表現図が適している。', '相対値は、色の濃さで区分する階級区分図が適している。', '人口を階級区分図にすると、面積の広い北海道などが濃く目立ち、多さを誤って印象づけるので避ける。'], a: '人口は図形表現図(またはドットマップ)、人口密度は階級区分図', check: '「面積が大きいほど値が大きくなりやすい数値か」を考えると、絶対値か相対値かを判断できます。' }] },
      { h: '地理情報システム(GIS)と位置情報', t: '【GIS(地理情報システム)】は、位置の情報をもつさまざまなデータをコンピュータ上で重ね合わせ、表示・分析する仕組みです。\nなぜ重ねるのが大切なのでしょうか。たとえば「浸水しやすい場所」の地図と「高齢者の多い地区」の地図を別々に見ても分かりにくいことが、重ねると「避難に助けが必要な人が多い危険な地区」として見えてくるからです。データの1枚1枚を【レイヤー】といいます。\n位置の情報は、人工衛星の電波で現在地を知る【GNSS】(衛星測位システム。アメリカのGPSや日本の準天頂衛星システム「みちびき」など)で得られます。スマートフォンの地図アプリやカーナビもこの仕組みを使っています。\n人工衛星や航空機から、離れた所の地表のようすを観測する技術を【リモートセンシング】(遠隔探査)といいます。森林の減少や、災害の被害の範囲を広くつかむのに役立ちます。\n日本では国土地理院の【地理院地図】をウェブ上で使うことができ、地形図・空中写真・標高などを重ねて見られます。GISは、防災、商店の出店計画、交通、農業など多くの場面で使われています。',
        key: 'GIS=位置情報をもつデータ(レイヤー)を重ねて分析する道具。位置はGNSS、地表の観測はリモートセンシング。',
        ex: [{ q: 'ある市が、大雨のときの避難計画をGISでつくる。重ね合わせると役立つレイヤーを3つ挙げ、何が分かるか説明しよう。', hint: '危険な場所・守る必要がある人・逃げる先を考えます。', steps: ['危険な場所を知るために、洪水の浸水想定区域や土砂災害警戒区域のレイヤーを用意する。', '守る必要がある人を知るために、高齢者や子どもの人口分布のレイヤーを用意する。', '逃げる先と道を知るために、避難所の位置と道路のレイヤーを用意する。', '重ねると、浸水しやすく高齢者が多い地区から、浸水しない道を通って行ける避難所が分かる。'], a: '浸水想定区域・人口(高齢者)分布・避難所と道路。重ねると、優先して支援すべき地区と安全な避難経路が分かる。', check: 'どのレイヤーも「位置」の情報をもっているかを確かめると、GISで重ねられるデータかどうか判断できます。' }] },
      { h: '地形図の読み取りと計算', t: '高校の地理でも、地形図の読み取りはよく出題されます。まず【縮尺】を確かめましょう。2万5千分の1なら地図上1cmが250m、5万分の1なら500mです。\n実際の距離=地図上の長さ×縮尺の分母、で求めます。単位をcm→m→kmと順に直すと、まちがいが減ります。\n面積は「たて×よこ」なので、縮尺の分母を2回かけることになります。2万5千分の1の地形図で一辺2cmの正方形は、実際には一辺500mの正方形で、面積は0.25km²です。\n等高線の間隔は、2万5千分の1では主曲線10m・計曲線50m、5万分の1では主曲線20m・計曲線100mです。等高線の間隔がせまいほど傾斜が急で、広いほどゆるやかです。\n等高線が山頂から低い方へ張り出している所は【尾根】、高い方へ入りこんでいる所は【谷】です。谷には水が集まるので川が流れています。',
        key: '実際の距離=地図上の長さ×縮尺の分母。面積は分母を2回かける。等高線が密なら急斜面。',
        ex: [{ q: '2万5千分の1の地形図上で、A地点とB地点の間が6cmあった。実際の距離は何km?また、A地点が標高50mの計曲線上、B地点が標高120mの地点のとき、2地点の標高差は何m?', hint: 'cmからkmへ、単位を順に直しましょう。', steps: ['実際の距離=6cm×25000=150000cm。', '150000cm=1500m=1.5km。', '標高差は120−50=70m。'], a: '距離は1.5km、標高差は70m', check: '1cmが250mなので、6cmは250×6=1500m=1.5kmと別の方法でも確かめられます。' }] }
    ],
    faq: [
      ['メルカトル図法は面積がゆがむのに、なぜ今も使われているの?', '角度が正しく、方位を一定にして進むコース(等角航路)が直線になるので、海図として便利だったからです。\nまた、狭い範囲を拡大しても形がくずれにくいので、ウェブ地図には、メルカトル図法を少し変えた図法が広く使われています。'],
      ['正距方位図法で、中心以外の2地点の距離は正しくないの?', '正しくありません。距離と方位が正しいのは「図の中心から」だけです。\nたとえば東京中心の正距方位図法でロンドンとニューヨークの距離を測っても、正しい値にはなりません。問題文で「中心はどこか」を必ず確かめましょう。'],
      ['日付変更線はなぜ曲がっているの?', 'ほぼ180度の経線にそって引かれていますが、同じ国や島々の中で日付がちがうと不便なので、陸地や国の境をさけるように曲げられています。']
    ],
    terms: [['図法(投影法)', '球である地球の表面を平面に表す方法'], ['等角航路', '経線と常に同じ角度で交わるコース。メルカトル図法では直線になる'], ['大圏航路', '地球上の2点間の最短コース。正距方位図法では中心から引いた直線になる'], ['標準時子午線', 'その国の時刻の基準となる経線。日本は東経135度'], ['階級区分図', '数値を階級に分け、色の濃さなどで表す統計地図。相対値に向く'], ['GIS', '位置情報をもつデータを重ね合わせて表示・分析する地理情報システム'], ['GNSS', '人工衛星を使って現在地を測る衛星測位システム。GPSなど'], ['リモートセンシング', '人工衛星などから離れた所の地表を観測する技術']],
    miss: ['メルカトル図法の直線を最短コースだと思ってしまう。直線は等角航路で、最短は大圏航路(北半球では高緯度側にふくらむ曲線)。「角度が正しい図法」と覚えておけば区別できる。', '正距方位図法で、中心以外の2地点間の距離も正しいと考えてしまう。正しいのは中心からの距離と方位だけと、問題を解く前に中心を確認する。', '時差の計算で、西にある地点の時刻を進めてしまう。地球は西から東へ回るので「東ほど進んでいる」と理由ごと覚える。', '人口などの絶対値を階級区分図で表してしまう。面積が広い地域が強調されるので、量は図形表現図、割合や密度は階級区分図と使い分ける。'],
    sum: ['地図は必ずゆがむので、目的に合わせて正しく表す性質を選ぶ。', 'メルカトル=正角(海図)、正距方位=中心からの距離と方位(航空図)、モルワイデ・サンソン・グード=正積(分布図)。', '経度差÷15=時差。東の方が進んでいる。東経と西経は経度を足す。', '統計地図は、相対値なら階級区分図、絶対値なら図形表現図やドットマップ。', 'GISは位置情報をもつデータを重ねて分析し、防災や都市計画に役立つ。'],
    next: '次は「気候のしくみとケッペンの気候区分(gg_climate)」へ進みましょう。ここで学んだ緯度や地図の読み方を使って、世界の気候の分布を理由とともに理解します。'
  };

  // ===== 気候のしくみとケッペンの気候区分 =====
  L.gg_climate = {
    goal: '気温と降水の分布を、太陽の当たり方・気圧帯・風・海流で説明でき、ケッペンの気候区分を雨温図から判定し、気候と植生・土壌・暮らしを結びつけられるようになる。',
    intro: '同じ「夏」でも、東京は蒸し暑く、ローマはからりと晴れ、シンガポールは毎日のようにスコール(激しいにわか雨)が降ります。こうしたちがいは、でたらめに決まっているわけではありません。地球全体の空気の流れには決まったパターンがあり、それに海や山の影響が加わって、各地の気候ができています。この単元では、まず気候が生まれるしくみを理解し、次にケッペンの気候区分で世界を整理します。',
    pre: '【気候】とは、ある地域で毎年くり返される、長い期間の平均的な大気の状態のことです。毎日変わる晴れ・雨などの【天気】とは区別します。気候は、気温・降水量・風などの【気候要素】で表します。\n気候要素に影響をあたえる条件を【気候因子】といいます。緯度、海からの距離、標高、海流、地形などがあります。\n中学では、世界の気候を熱帯・乾燥帯・温帯・冷帯(亜寒帯)・寒帯の5つに分けました。高校ではこれをさらに細かく分け、その理由まで考えます。\n【雨温図】は、月ごとの平均気温を折れ線グラフ、降水量を棒グラフで表した図です。気候区分の判定に使います。\n空気は温められると軽くなって上昇し(上昇気流)、地表付近の気圧が低くなります。上昇した空気は冷えて雲ができ、雨が降りやすくなります。逆に空気がおりてくる(下降気流)所は気圧が高く、雲ができにくく晴れやすくなります。',
    secs: [
      { h: '気温を決めるもの:緯度・標高・海と陸', t: 'なぜ赤道付近は暑く、極付近は寒いのでしょうか。赤道付近では太陽の光が真上近くから当たり、同じ面積に多くの熱が届くからです。極に近いほど光がななめに当たり、熱が広い面積に分散します。\n標高が高い所ほど気温は下がります。その割合(【気温の逓減率】)は、100mあたり約0.65℃です。赤道直下でも、アンデス山脈の高地にあるキトやラパスがすずしいのはこのためです。\n海は陸より温まりにくく冷めにくい性質があります。そのため、海に近い所は気温の年較差(最暖月と最寒月の差)が小さく(【海洋性気候】)、大陸の内部は年較差が大きく(【大陸性気候】)なります。\n【海流】も気温に影響します。暖流が流れる沿岸は暖かく、寒流が流れる沿岸はすずしくなります。寒流の沿岸では下層の空気が冷やされて上昇気流ができにくく、雨が少なくなります。アフリカ南西部のナミブ砂漠や、南アメリカ西岸のアタカマ砂漠は、寒流の影響でできた海岸砂漠です。',
        key: '気温は緯度で大まかに決まり、標高(100mで約0.65℃下がる)・海からの距離・海流で変わる。',
        ex: [{ q: '海抜0mの平均気温が28℃の地域で、標高3000mの高地の平均気温はおよそ何℃?(気温の逓減率を100mあたり0.65℃とする)', hint: '3000mは100mの何倍かを考えます。', steps: ['3000mは100mの30倍。', '下がる気温は0.65×30=19.5℃。', '28−19.5=8.5℃。'], a: '約8.5℃', check: '1000mで約6.5℃下がるので、3000mで約19.5℃と考えても同じ値になります。' }] },
      { h: '大気の大循環:気圧帯と恒常風', t: '地球全体では、空気が決まったパターンで動いています。これを【大気の大循環】といいます。\n赤道付近では強い日射で空気が温められて上昇し、【赤道低圧帯】(熱帯収束帯)ができます。上昇した空気から雲ができ、雨が多くなります。\n上昇した空気は高い所を極の方へ流れ、緯度20〜30度付近でおりてきます。ここが【亜熱帯高圧帯】で、下降気流のため雲ができにくく、世界の大きな砂漠(サハラ砂漠など)が多く分布します。\n緯度60度付近には【亜寒帯低圧帯】、極付近には冷たく重い空気がたまる【極高圧帯】があります。\n風は気圧の高い所から低い所へふきます。亜熱帯高圧帯から赤道低圧帯へふく風が【貿易風】(北半球では北東風)、亜熱帯高圧帯から亜寒帯低圧帯へふく風が【偏西風】、極高圧帯からふき出す風が【極東風】です。地球の自転の影響で、風の向きは北半球では進む方向の右へ曲げられます。\n太陽が真上から当たる位置は季節によって南北に移るので、気圧帯も夏は高緯度側、冬は低緯度側へずれます。この「季節による移動」が、雨季と乾季をもつ気候や、夏に乾燥する気候を生みます。',
        key: '赤道低圧帯=雨が多い、亜熱帯高圧帯=乾燥(砂漠)。貿易風・偏西風・極東風。気圧帯は季節で南北に移動する。',
        fig: CIRC,
        ex: [{ q: 'サバナ気候(Aw)の地域に、雨季と乾季がはっきりあるのはなぜ?気圧帯の移動を使って説明しよう。', hint: 'サバナ気候は、赤道低圧帯と亜熱帯高圧帯の間にあります。', steps: ['サバナ気候は、熱帯雨林気候の外側(赤道からやや離れた低緯度)に分布する。', '夏(太陽が真上近くに来る時期)には、赤道低圧帯がこの地域まで移ってきて上昇気流が生じ、雨が多くなる。', '冬には、亜熱帯高圧帯がこの地域まで移ってきて下降気流が生じ、乾燥する。', 'このように、季節によっておおわれる気圧帯が入れかわるため、雨季と乾季が生まれる。'], a: '夏は赤道低圧帯におおわれて雨季、冬は亜熱帯高圧帯におおわれて乾季になるから。', check: '北半球と南半球で雨季の時期が反対になる(北半球は6〜8月ごろ、南半球は12〜2月ごろ)ことと合っているか確かめます。' }] },
      { h: '季節風と地形の影響', t: '大陸と海洋の温まり方のちがいから、季節によって向きが変わる風を【季節風】(モンスーン)といいます。\n夏は大陸が海より強く温められて低圧になり、海から大陸へ湿った風がふきこみます。冬は大陸が冷えて高圧になり、大陸から海へ乾いた冷たい風がふき出します。\n特に東アジア・東南アジア・南アジアでは季節風の影響が大きく、夏の多雨が稲作を支えています。インドのアッサム地方などは、夏の季節風が山地にぶつかって世界でも有数の多雨地域になっています。\n山地も降水に大きく影響します。湿った風が山にぶつかって上昇すると雲ができ、風上側に雨が多く降ります。山をこえた風下側では乾燥した風がふきおろし、雨が少なくなります。日本の冬、日本海側に雪が多く太平洋側が晴れるのはこのためです。\nまた、熱帯の海上で発生する強い低気圧(熱帯低気圧)は、地域によって台風(東アジア)、サイクロン(インド洋)、ハリケーン(北アメリカ周辺)とよばれ、強風と大雨をもたらします。',
        key: '季節風は夏は海→大陸(湿った風・多雨)、冬は大陸→海(乾いた風)。山の風上は多雨、風下は少雨。' },
      { h: 'ケッペンの気候区分:判定の手順', t: 'ドイツの気候学者【ケッペン】は、気候のちがいが最もよく表れるのは植物(植生)だと考え、植生の分布に合わせて気温と降水量の基準を決めました。\nまず、樹木が育つかどうかで分けます。樹木が育たない気候(【無樹林気候】)は、寒さで育たない【寒帯(E)】と、乾燥で育たない【乾燥帯(B)】です。樹木が育つ気候(【樹林気候】)は、熱帯(A)・温帯(C)・冷帯(D)です。\n判定は、下の鎖の順に進めます。最暖月が10℃未満なら寒帯、乾燥限界より降水が少なければ乾燥帯、それ以外は最寒月の気温で熱帯・温帯・冷帯に分けます。\nさらに降水の季節的なかたよりで細かく分けます。f は1年中降水がある、s は夏に乾燥、w は冬に乾燥、m は弱い乾季がある(熱帯モンスーン気候 Am)ことを表します。\n乾燥帯は、草原が広がる【ステップ気候(BS)】と、植物がほとんど育たない【砂漠気候(BW)】に分けます。寒帯は、最暖月0℃以上10℃未満の【ツンドラ気候(ET)】と、0℃未満の【氷雪気候(EF)】に分けます。\n温帯の Cfa(温暖湿潤気候)と Cfb(西岸海洋性気候)は、最暖月が22℃以上かどうかで分けます。',
        key: '判定順:最暖月10℃未満→E、乾燥→B、最寒月18℃以上→A、−3℃以上→C、−3℃未満→D。f=年中湿潤、s=夏乾燥、w=冬乾燥。',
        chain: { title: 'ケッペンの気候区分の判定(上から順に)', items: [
          ['1', '最暖月が10℃未満 → 寒帯(E)', '0℃未満なら氷雪気候(EF)、0〜10℃ならツンドラ気候(ET)'],
          ['2', '降水量が乾燥限界より少ない → 乾燥帯(B)', '草原ならステップ(BS)、ほとんど植物がなければ砂漠(BW)'],
          ['3', '最寒月が18℃以上 → 熱帯(A)', 'Af・Am・Aw'],
          ['4', '最寒月が−3℃以上18℃未満 → 温帯(C)', 'Cfa・Cfb・Cs・Cw'],
          ['5', '最寒月が−3℃未満 → 冷帯(D)', 'Df・Dw(最暖月は10℃以上)']] },
        ex: [
          { q: 'ある地点の雨温図で、最寒月平均気温は5℃、最暖月平均気温は27℃、1年中降水が多かった。この地点の気候区分は?', hint: '判定の鎖を上から順に当てはめます。', steps: ['最暖月27℃なので寒帯ではない。1年中降水が多いので乾燥帯でもない。', '最寒月5℃は18℃未満で−3℃以上なので温帯(C)。', '1年中降水があるので f、最暖月が22℃以上なので a。'], a: '温暖湿潤気候(Cfa)', check: '東京や上海など、大陸の東岸の中緯度に分布する気候と同じ特徴か確かめます。' },
          { q: '1月が最も暑く(平均気温25℃)、7月が最も寒い(平均気温12℃)、7月ごろに雨が多く1月ごろはほとんど雨が降らない地点がある(年降水量は乾燥限界をこえている)。この地点は北半球と南半球のどちらにあり、気候区分は何?', hint: '最も暑い月がいつかで半球が分かります。夏に雨が少ないのはどの気候でしょう。', steps: ['1月が最も暑いので、この地点は【南半球】にある(南半球では1月ごろが夏)。', '最寒月12℃は18℃未満で−3℃以上なので温帯(C)。', '雨の少ない1月ごろは南半球の夏なので、「夏に乾燥」の s。', 'よって地中海性気候(Cs)。南半球では、オーストラリア南西部(パース)やアフリカ南端(ケープタウン)付近などに見られる。'], a: '南半球。地中海性気候(Cs)', check: '北半球の地中海性気候(ローマなど)の雨温図を半年ずらした形になっているか確かめます。' },
          { q: '最暖月平均気温が6℃の地点の気候区分と、そこで見られる植生は?', hint: '判定の鎖の1番目に当てはまります。', steps: ['最暖月が10℃未満なので寒帯(E)。', '最暖月が0℃以上なのでツンドラ気候(ET)。', '短い夏に地表の氷がとけ、こけ類や地衣類が育つ。地下には一年中とけない永久凍土がある。'], a: 'ツンドラ気候(ET)。こけ類・地衣類などのツンドラ', check: '最暖月が0℃未満なら氷雪気候(EF)になるので、0℃より上か下かを確かめます。' }
        ] },
      { h: '仮想大陸で見る気候の分布', t: '気候区分の分布には決まりがあります。これを1つの大陸にまとめたのが【仮想大陸】の模式図です。下の図は北半球の大陸を、西岸・内陸・東岸に分けて表したものです。\n赤道付近には熱帯雨林気候(Af)、その外側にサバナ気候(Aw)が広がります。\n緯度20〜30度付近の大陸西岸から内陸には、亜熱帯高圧帯の影響で砂漠気候(BW)が広がり、その周りにステップ気候(BS)があります。\n中緯度の西岸には、夏に亜熱帯高圧帯、冬に偏西風の影響を受ける地中海性気候(Cs)、その高緯度側に西岸海洋性気候(Cfb)があります。西ヨーロッパは、暖流の【北大西洋海流】の上をわたってくる偏西風のおかげで、高緯度なのに冬も温和です。\n中緯度の東岸には、季節風の影響を受ける温暖湿潤気候(Cfa)や温暖冬季少雨気候(Cw)があります。高緯度の大陸内部や東岸には冷帯が広がり、冬に大陸の高気圧(シベリア高気圧)が発達するユーラシア東部では、冬に乾燥する冷帯冬季少雨気候(Dw)になります。\n冷帯(D)は北半球にだけ分布します。南半球には、その緯度帯に大きな陸地がないからです。',
        key: '西岸は「砂漠→地中海性→西岸海洋性」、東岸は「季節風の影響(Cfa・Cw・Dw)」。冷帯は北半球だけ。',
        tmap: { title: '仮想大陸の気候区分(北半球・模式図)', cols: 3, rows: 6,
          cells: [
            ['寒帯 ET・EF', 'k', 1, 1, 3, 1, '高緯度(北極の周り)'],
            ['西岸海洋性 Cfb', 'gr', 1, 2, 1, 1, '偏西風と暖流'], ['冷帯湿潤 Df', 'b', 2, 2, 1, 1, '内陸・タイガ'], ['冷帯 Dw・Df', 'b', 3, 2, 1, 1, '東岸・冬に乾燥'],
            ['地中海性 Cs', 'y', 1, 3, 1, 1, '夏に乾燥'], ['ステップ BS', 'o', 2, 3, 1, 1, '内陸の草原'], ['温暖湿潤 Cfa', 'gr', 3, 3, 1, 1, '季節風'],
            ['砂漠 BW', 'o', 1, 4, 2, 1, '亜熱帯高圧帯・寒流'], ['温暖冬季少雨 Cw', 'gr', 3, 4, 1, 1, '季節風'],
            ['サバナ Aw', 'r', 1, 5, 3, 1, '雨季と乾季'],
            ['熱帯雨林 Af', 'rr', 1, 6, 3, 1, '赤道付近・1年中多雨']
          ],
          legend: [['rr', '熱帯'], ['o', '乾燥帯'], ['gr', '温帯'], ['y', '温帯(夏乾燥)'], ['b', '冷帯'], ['k', '寒帯']],
          note: '左が大陸の西岸、右が東岸、上ほど高緯度。実際の大陸の形や面積ではなく、分布の傾向だけを表した模式図です。' } },
      { h: '気候と植生・土壌・暮らし', t: '気候は植物の育ち方を決め、植物と気候は土壌(土)の性質を決めます。そして人々は、その環境に合わせて暮らしを工夫してきました。\n【熱帯】:熱帯雨林気候では、常緑広葉樹の密林が広がります。アマゾン川流域の熱帯雨林は【セルバ】とよばれます。多雨で養分が流されやすく、赤色のやせた【ラトソル】が分布します。風通しをよくし湿気をさける【高床式の住居】が見られます。サバナ気候では、まばらな樹木と背の高い草原(サバナ)が広がります。\n【乾燥帯】:砂漠では、わき水や地下水が得られる【オアシス】で、なつめやしや小麦などを育てるオアシス農業が行われます。イランでは【カナート】とよばれる地下水路で水を引きます。木材が少ないので【日干しれんが】の家が多く、ステップでは家畜とともに移動する【遊牧】も行われます。ウクライナなどのステップには、肥沃な黒土【チェルノーゼム】が分布し、世界的な小麦の産地です。\n【温帯】:地中海性気候の地域では、夏の乾燥に強いオリーブ・ぶどう・柑橘類が栽培されます。地中海沿岸には石灰岩が風化した赤い土【テラロッサ】が見られます。\n【冷帯】:針葉樹林の【タイガ】が広がり、灰白色のやせた【ポドゾル】が分布します。地下の【永久凍土】が建物の熱でとけて家がかたむくのを防ぐため、高床にした建物が見られます。\n【寒帯】:ツンドラでは、イヌイットなどの人々がアザラシやカリブーの狩猟、トナカイの遊牧などを行ってきました。',
        key: 'ラトソル(熱帯・やせた赤土)、チェルノーゼム(ステップ・肥沃な黒土)、ポドゾル(タイガ・やせた灰白色土)、テラロッサ(地中海・石灰岩の赤土)。',
        ex: [{ q: '熱帯雨林は植物がよく育つのに、その土壌(ラトソル)がやせているのはなぜ?', hint: '雨の多さと、落ち葉の分解の速さを考えます。', steps: ['熱帯雨林気候は1年中高温多雨である。', '高温のため落ち葉などの有機物はすぐに分解され、養分は植物にすぐ吸収されるので、土の中に養分がたまりにくい。', 'さらに大量の雨で、土の中の養分が流し去られる。', 'あとには鉄やアルミニウムの酸化物が残り、赤色のやせた土になる。'], a: '高温で有機物の分解が速く、多雨で養分が流されるため、土壌に養分がたまらないから。', check: '森林を伐採すると、土地がすぐにやせて農業が長続きしない(焼畑農業で耕地を移す理由)こととつながっているか確かめます。' }] }
    ],
    faq: [
      ['ケッペンの区分で「乾燥限界」はどう決めるの?', '年平均気温と降水の季節配分から計算する値で、気温が高いほど蒸発が多いので乾燥限界の値も大きくなります。\n高校の問題では計算まで求められることは少なく、「年降水量がかなり少なく、草原や砂漠が広がる」ことから乾燥帯と判断するのがふつうです。'],
      ['日本はどの気候区分になるの?', '本州・四国・九州の大部分は温暖湿潤気候(Cfa)、北海道の大部分は冷帯湿潤気候(Df)です。\n標高の高い地域や、南西諸島の一部などは、これと異なる区分になることもあります。'],
      ['高山気候(H)はケッペンの区分にあるの?', 'ケッペン自身の区分にはなく、のちに標高の高い地域を表すために加えられたものです。\n赤道付近でも高地では年中すずしく、気温の年較差が小さいのが特徴です。アンデス山脈のラパスなどが例です。']
    ],
    terms: [['気温の逓減率', '標高が100m上がるごとに気温が約0.65℃下がる割合'], ['亜熱帯高圧帯', '緯度20〜30度付近にできる高気圧の帯。下降気流で乾燥し砂漠が多い'], ['偏西風', '中緯度で1年中西から東へふく風'], ['貿易風', '亜熱帯高圧帯から赤道低圧帯へふく東寄りの風'], ['季節風(モンスーン)', '夏と冬で向きが変わる風'], ['セルバ', 'アマゾン川流域の熱帯雨林'], ['タイガ', '冷帯に広がる針葉樹林'], ['チェルノーゼム', 'ウクライナなどのステップに分布する肥沃な黒色土']],
    miss: ['雨温図を見るとき、南半球の地点なのに7月を夏と考えてしまう。最も暑い月が1月なら南半球、と最初に確認する。', '冷帯と寒帯の基準を混同する。寒帯は「最暖月10℃未満」、冷帯は「最寒月−3℃未満で最暖月10℃以上」と、見る月がちがうことに注意する。', '地中海性気候(Cs)を「冬に乾燥」と覚えてしまう。夏は亜熱帯高圧帯におおわれて乾燥すると、しくみから覚えれば逆にならない。', '砂漠はすべて赤道付近の暑い所にあると考える。亜熱帯高圧帯のほか、寒流の沿岸(海岸砂漠)や大陸内部(ゴビ砂漠など)にも砂漠はある。'],
    sum: ['気温は緯度・標高・海からの距離・海流で決まる。標高100mで約0.65℃下がる。', '赤道低圧帯は多雨、亜熱帯高圧帯は乾燥。気圧帯は季節で南北に移動し、雨季・乾季を生む。', 'ケッペンは植生に注目して、A・B・C・D・Eの5つの気候帯に分けた。', '大陸の西岸と東岸では気候の並び方がちがう。冷帯は北半球にだけある。', '気候は植生・土壌・住居・農業など人々の暮らしと深く結びついている。'],
    next: '次は「大地形とプレート・小地形(gg_landform)」へ進みましょう。気候とならぶ自然環境のもう1つの柱である地形を、プレートの動きと川や海のはたらきから理解します。'
  };

  var FAN = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="扇状地の模式図。谷口の扇頂から扇形に広がり、扇央では川の水が地下にしみこみ、扇端でわき出す"><path d="M10 32 L45 10 L80 30 L110 12 L140 30 L175 8 L210 32" class="ax"/><path d="M110 30 L40 112 Q110 132 180 112 Z" class="fl"/><path d="M110 30 L40 112 Q110 132 180 112 Z" class="rt"/><path d="M84 60 Q110 68 136 60" class="dash"/><path d="M58 96 Q110 112 162 96" class="dash"/><path d="M110 30 L112 60" class="cv"/><path d="M112 60 L114 100" class="dash"/><path d="M114 112 L116 138" class="cv"/><circle cx="114" cy="112" r="3" class="pt"/><text x="14" y="50">山地</text><text x="120" y="50">扇頂</text><text x="64" y="84">水無川</text><text x="120" y="86">扇央:畑・果樹</text><text x="16" y="146">扇端:わき水・集落・水田</text></svg>';
  var THUNEN = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="チューネンの孤立国の模式図。都市を中心に、野菜・牛乳、林業、穀物、牧畜の順に同心円状に並ぶ"><circle cx="75" cy="75" r="60" class="rt"/><circle cx="75" cy="75" r="44" class="rt"/><circle cx="75" cy="75" r="28" class="rt"/><circle cx="75" cy="75" r="12" class="tr"/><text x="69" y="79">1</text><text x="72" y="59">2</text><text x="72" y="43">3</text><text x="72" y="27">4</text><text x="16" y="22">5</text><text x="142" y="30">1 都市(市場)</text><text x="142" y="52">2 野菜・牛乳</text><text x="142" y="74">3 林業(燃料)</text><text x="142" y="96">4 穀物</text><text x="142" y="118">5 牧畜</text><text x="8" y="146">都市から遠いほど土地を広く使う</text></svg>';

  // ===== 大地形とプレート・小地形 =====
  L.gg_landform = {
    goal: '大地形をプレートの動きと造山運動の時代で区分して説明でき、扇状地・三角州・海岸地形などの小地形のでき方と土地利用・災害との関係を説明できるようになる。',
    intro: '日本アルプスの高い山々も、平野の田んぼも、海岸の入り組んだ湾も、長い時間をかけて地球がつくってきた形です。地形をつくる力には2つあります。地球の内部から大地をもち上げたり動かしたりする力と、川・海・氷河・風などが地表をけずったり運んだりする力です。この単元では、まず大陸や山脈のような大きな地形を、次に扇状地や三角州のような身近な地形を学びます。地形が分かると、「なぜそこに田んぼがあるのか」「なぜそこで水害が起きやすいのか」が見えてきます。',
    pre: '中学では、日本の地形として、川が山地から平野に出る所にできる【扇状地】と、河口にできる【三角州】を学びました。また、日本は山地が国土の約4分の3をしめ、川が短く急流であることも学びました。\n地形図では、等高線の間隔がせまいほど急な斜面、広いほどゆるやかな斜面を表します。\n地球の表面は、厚さ数十〜100km程度のかたい岩の板(【プレート】)でおおわれています。プレートは1年に数cmほどのゆっくりした速さで動いています。\n地震は、プレートの境目や断層で岩盤が急にずれることで起こります。火山は、地下でできたマグマが地表にふき出してできます。\n地質の時代は、古い順に【先カンブリア時代】、【古生代】、【中生代】、【新生代】と区分されます。この単元ではこの順番を使います。',
    secs: [
      { h: '地形をつくる2つの力', t: 'なぜ地形はいろいろな形をしているのでしょうか。地形は、2つの力の「せめぎあい」でつくられるからです。\n1つ目は地球の内部からはたらく【内的営力】です。地殻変動(大地のもち上がり・しずみこみ・ずれ)や火山活動などで、山地や盆地のような大きな起伏をつくります。\n2つ目は太陽のエネルギーを源にして地表ではたらく【外的営力】です。岩石が細かくくだける【風化】、流水などがけずる【侵食】、土砂を運ぶ【運搬】、積もらせる【堆積】があり、高い所をけずって低い所をうめ、起伏を小さくする方向にはたらきます。\n内的営力でできる大陸・山脈・海溝などの大規模な地形を【大地形】、外的営力でできる扇状地・三角州・海岸の地形などを【小地形】とよびます。\nたとえば日本アルプスは、内的営力でもち上げられた山が、川や氷河にけずられて今の形になりました。けずられた土砂は川に運ばれ、ふもとに扇状地や平野をつくりました。',
        key: '内的営力(地殻変動・火山)は起伏を大きく、外的営力(風化・侵食・運搬・堆積)は起伏を小さくする。' },
      { h: 'プレートの境界と変動帯', t: 'プレートどうしの境界では、大地の動きが活発です。こうした所を【変動帯】といい、地震や火山が集中します。境界には3つの種類があります。\n【広がる境界】:プレートどうしが離れていく所です。地下からマントルの物質がわき上がり、新しいプレートがつくられます。海底では大山脈の【海嶺】(大西洋中央海嶺など)ができます。陸上では、アフリカ大地溝帯のような大きな裂け目ができます。アイスランドは大西洋中央海嶺が海面上に出た島で、火山が多く地熱の利用がさかんです。\n【せばまる境界】:プレートどうしが近づく所です。海洋プレートが大陸プレートの下にしずみこむ所には、深い溝の【海溝】ができ、その陸側に日本列島のような【弧状列島】や火山が並びます。大陸プレートどうしが衝突すると、ヒマラヤ山脈のような高い山脈ができます。\n【ずれる境界】:プレートどうしがすれちがう所です。アメリカ西部のサンアンドレアス断層が代表例です。\nなお、プレートの境界ではない所でも、地下深くからマグマが上がってくる【ホットスポット】では火山ができます。ハワイ諸島がその例です。',
        key: '広がる境界=海嶺・地溝帯、せばまる境界=海溝・弧状列島・大山脈、ずれる境界=横ずれ断層。',
        ex: [{ q: '日本列島に地震や火山が多い理由を、プレートを使って説明しよう。', hint: '日本列島の近くにあるのは、どの種類のプレート境界でしょうか。', steps: ['日本列島付近では、太平洋プレートやフィリピン海プレートなどの海洋プレートが、ユーラシアプレートや北アメリカプレートの下にしずみこんでいる。', 'これは「せばまる境界」にあたり、海側には日本海溝や南海トラフなどの深い溝ができている。', 'しずみこむプレートに引きずられた陸側のプレートがはね返ったり、岩盤が割れたりして、大きな地震が起こる。', 'しずみこんだプレートの上の地下深くでマグマができ、火山が列をなして分布する。'], a: '日本列島は海洋プレートが大陸側のプレートの下にしずみこむ「せばまる境界」にあり、ひずみの解放で地震が起き、マグマができて火山が多いから。', check: '世界の地震・火山の分布図で、環太平洋の海溝ぞいに地震と火山が集中していることと合っているか確かめます。' }] },
      { h: '大地形の区分:安定陸塊・古期造山帯・新期造山帯', t: '陸上の大地形は、最後に大きな造山運動(山をつくる地殻変動)を受けた時代によって3つに分けられます。\n【安定陸塊】は、先カンブリア時代に造山運動を受けたあと、長い間侵食を受けてきた平らな土地です。古い岩盤がむき出しの【楯状地】(カナダ楯状地、バルト楯状地など)と、その上に地層がほぼ水平に積もった【卓状地】(東ヨーロッパ平原など)があります。【鉄鉱石】の産地が多く分布します。\n【古期造山帯】は、古生代に造山運動を受けた山地で、長い侵食により比較的低くなだらかになっています。アパラチア山脈、ウラル山脈、スカンディナヴィア山脈、グレートディヴァイディング山脈などです。古生代の植物が地中にうもれてできた【石炭】が多く分布します。\n【新期造山帯】は、中生代から新生代にかけて造山運動を受け、今も活動が続く山地です。高くけわしい山が多く、地震や火山が多発します。太平洋を取りまく【環太平洋造山帯】(アンデス山脈、ロッキー山脈、日本列島など)と、ヨーロッパからアジアへ東西にのびる【アルプス=ヒマラヤ造山帯】の2つがあります。周辺には石油の産地や、銅などの金属資源が多い所もあります。',
        key: '安定陸塊(先カンブリア・平ら・鉄鉱石)、古期造山帯(古生代・なだらか・石炭)、新期造山帯(中生代以降・けわしい・地震と火山)。',
        flow: { title: '大地形の3区分', cols: 3, head: ['安定陸塊', '古期造山帯', '新期造山帯'], rows: [
          [['先カンブリア時代', 'k'], ['古生代', 'g'], ['中生代〜新生代', 'r']],
          [['平原・台地', 'k', 1, '楯状地・卓状地'], ['低くなだらかな山地', 'g', 1, '長い侵食'], ['高くけわしい山地', 'r', 1, '地震・火山が多い']],
          [['鉄鉱石', 'k'], ['石炭', 'g'], ['石油・銅など', 'r']],
          [['カナダ楯状地など', 'k'], ['アパラチア・ウラル', 'g'], ['アンデス・ヒマラヤ', 'r']]
        ], legend: [['k', '安定陸塊'], ['g', '古期造山帯'], ['r', '新期造山帯']] },
        ex: [{ q: 'ウラル山脈がヒマラヤ山脈よりずっと低くなだらかなのはなぜ?', hint: 'それぞれの山脈が、いつ造山運動を受けたかを考えます。', steps: ['ウラル山脈は古期造山帯で、古生代に造山運動を受けた。', 'ヒマラヤ山脈は新期造山帯で、今もインド=オーストラリアプレートとユーラシアプレートの衝突が続き、もち上げられている。', 'ウラル山脈は造山運動が終わったあと、非常に長い時間、侵食を受け続けてきた。', 'そのため、けずられて低くなだらかになった。'], a: 'ウラル山脈は古生代に造山運動を受けたあと長く侵食されてきた古期造山帯で、ヒマラヤ山脈は今も隆起が続く新期造山帯だから。', check: '同じ古期造山帯のアパラチア山脈やグレートディヴァイディング山脈もなだらかであることと一致するか確かめます。' }] },
      { h: '川がつくる地形:扇状地', t: '川は、上流で谷をけずり、中流・下流で土砂を積もらせて平野をつくります。山地では、川が深くけずって断面がV字の【V字谷】ができます。\n川が山地から平野に出る【谷口】では、川の傾きが急にゆるやかになって流れが弱まり、運んできた砂やれき(小石)が積もります。こうしてできた扇形の地形が【扇状地】です。\n扇状地は、谷口に近い【扇頂】、中央の【扇央】、末端の【扇端】に分けられます。扇央はれきが多く水はけがよすぎるので、川の水が地下にしみこみ、ふだんは水の流れない【水無川】になることがあります。水が得にくいため、昔は桑畑、現在は果樹園や畑に利用されることが多い土地です。\n地下を流れた水は、扇端で【わき水】(湧水)として地表に出てきます。そのため扇端には昔から集落が並び、水田も開かれてきました。甲府盆地の扇状地では、ぶどうやももの栽培がさかんです。\n扇状地の川は土砂が多く、堤防を高くしても川底に土砂がたまり続けて、川底が周りの土地より高くなる【天井川】ができることがあります。',
        key: '扇央=水が地下にしみこむ→畑・果樹園。扇端=わき水→集落・水田。',
        fig: FAN,
        ex: [{ q: '扇状地の扇端に集落が帯のように並んでいることが多いのはなぜ?', hint: '扇央でしみこんだ水がどこへ行くかを考えます。', steps: ['扇状地はれきや砂でできていて水はけがよいので、扇央では川の水が地下にしみこむ。', 'しみこんだ水は地下を流れ、扇状地の末端(扇端)でわき水として地表に出てくる。', '生活や農業に欠かせない水が得やすいので、扇端に沿って集落がつくられた。', '扇端は扇状地の末端に沿って弧のように続くので、集落も帯状に並ぶ。'], a: '扇央でしみこんだ水が扇端でわき出し、飲み水や水田の水を得やすいから。', check: '地形図で扇状地を見ると、扇端付近に水田と集落、扇央に果樹園の記号が多いかを確かめます。' }] },
      { h: '川がつくる地形:氾濫原・三角州・河岸段丘', t: '扇状地より下流の平野では、川は大きく曲がりくねって流れます(【蛇行】)。洪水のたびに川の水があふれて土砂を積もらせてできた平野を【氾濫原】といいます。\n洪水のとき、川の水があふれると、流れが弱まる川岸に砂が多く積もり、周りより少し高い【自然堤防】ができます。その外側には、細かい泥が積もった低く湿った【後背湿地】が広がります。自然堤防は水はけがよく洪水のときも水につかりにくいので集落や畑に、後背湿地は水田に使われてきました。\n蛇行していた川の流れが変わると、とり残された部分が三日月の形の湖(【三日月湖】)になります。北海道の石狩川流域でよく見られます。\n川が海や湖に流れこむ河口付近では、流れが弱まって細かい砂や泥が積もり、【三角州】(デルタ)ができます。低く平らで、水田や都市に利用されますが、高潮や洪水の被害を受けやすい土地です。広島市は太田川の三角州の上に発達しました。形は、ナイル川の円弧状、ミシシッピ川の鳥趾状(鳥のあしの形)などさまざまです。\n川ぞいに階段状の地形が見られることがあります。土地の隆起などで川が再び深くけずるようになり、もとの谷底がとり残されてできた地形で、【河岸段丘】といいます。段丘面は平らで水害を受けにくく、畑や集落に利用されます。',
        key: '自然堤防=少し高い→集落・畑、後背湿地=低く湿る→水田。三角州は河口の低平地で水害に注意。',
        ex: [{ q: '古い地形図で、川ぞいの細長い微高地に集落と畑があり、その外側に水田が広がっていた。この微高地の名前と、ここに集落がつくられた理由は?', hint: '洪水のとき、川からあふれた水が運んだ砂はどこに積もるでしょう。', steps: ['川からあふれた水は、川岸ですぐに流れが弱まり、粒の大きい砂が積もる。', 'こうして川ぞいにできた周りより少し高い土地が自然堤防である。', '自然堤防は水はけがよく、洪水のときも水につかりにくい。', 'そのため集落や畑に使われ、外側の低い後背湿地は水田に使われた。'], a: '自然堤防。周りより少し高く水はけがよく、洪水の被害を受けにくいから。', check: '現在は後背湿地にも住宅地が広がっている所があり、そこが浸水しやすいことがハザードマップで確かめられます。' }] },
      { h: '海岸の地形・氷河地形・カルスト地形', t: '海岸の地形は、土地がしずむか(または海面が上がるか)、もち上がるか(または海面が下がるか)で大きく変わります。\n【沈水海岸】は、陸地がしずんだり海面が上がったりしてできます。川がけずったV字谷が沈水すると、のこぎりの歯のように入り組んだ【リアス海岸】になります(三陸海岸南部、志摩半島、若狭湾など)。湾が深く波がおだやかなので、養殖業や漁港に適しています。一方で、津波が湾の奥で高くなりやすい危険もあります。氷河がけずったU字谷が沈水すると、奥行きの深い【フィヨルド】になります(ノルウェー、チリ南部、ニュージーランド南島など)。河口が沈水してラッパ状に広がった【エスチュアリー】(三角江)は、テムズ川やラプラタ川などに見られ、港が発達しやすい地形です。\n【離水海岸】は、海底がもち上がったり海面が下がったりしてできます。海底の平らな面が陸になった【海岸平野】(九十九里平野など)や、階段状の【海岸段丘】があります。\n海流などに運ばれた砂は、くちばしのように突き出た【砂嘴】(野付崎、三保松原)、湾をふさぐようにのびた【砂州】(天橋立)をつくります。砂州で島と陸地がつながると、その島を【陸繋島】といいます(函館山)。砂州で海から切り離された湖を【ラグーン】(潟湖)といいます(サロマ湖など)。\n熱帯の浅い海では、サンゴがつくる【サンゴ礁】が見られ、島を取りまく形から裾礁・堡礁・環礁に分けられます。\n氷河がけずった地形には、U字谷、山頂付近のおわん形のくぼみ【カール】、氷河が運んだ土砂の丘【モレーン】などがあります。石灰岩の地域では、雨水が岩をとかして【カルスト地形】ができ、すりばち形のくぼ地【ドリーネ】や鍾乳洞が見られます(秋吉台など)。',
        key: 'V字谷が沈水→リアス海岸、U字谷が沈水→フィヨルド、河口が沈水→エスチュアリー。離水すると海岸平野・海岸段丘。',
        flow: { title: '海岸地形の区分', cols: 3, head: ['でき方', '地形', '例'], rows: [
          [['V字谷が沈水', 'b'], ['リアス海岸', 'b', 1, '養殖・漁港'], ['三陸海岸南部・志摩半島', 'b']],
          [['U字谷が沈水', 'b'], ['フィヨルド', 'b', 1, '奥行きが深い'], ['ノルウェー・チリ南部', 'b']],
          [['河口が沈水', 'b'], ['エスチュアリー', 'b', 1, '港が発達'], ['テムズ川・ラプラタ川', 'b']],
          [['海底が離水', 'o'], ['海岸平野・海岸段丘', 'o'], ['九十九里平野', 'o']],
          [['砂の堆積', 'g'], ['砂嘴・砂州・陸繋島', 'g'], ['野付崎・天橋立・函館', 'g']]
        ], legend: [['b', '沈水海岸'], ['o', '離水海岸'], ['g', '砂がつくる地形']] },
        ex: [
          { q: 'リアス海岸とフィヨルドは、どちらも入り組んだ湾をもつ沈水海岸である。2つのでき方のちがいと、分布する地域の特徴を説明しよう。', hint: 'もとになった谷を、何がけずったかを考えます。', steps: ['リアス海岸は、川の侵食でできたV字谷が沈水してできた。', 'フィヨルドは、氷河の侵食でできたU字谷が沈水してできた。', '氷河は、かつて氷河が発達した高緯度地方や、その近くの山地に多かった。', 'そのためフィヨルドはノルウェーなど高緯度の地域に多く、リアス海岸は日本のような中緯度の地域にも見られる。'], a: 'リアス海岸は川がつくったV字谷、フィヨルドは氷河がつくったU字谷が沈水した。フィヨルドは氷河が発達した高緯度地方に多い。', check: '谷の断面の形(V字かU字か)と、湾の奥行き・がけの急さのちがいが結びついているか確かめます。' },
          { q: '三陸海岸のリアス海岸で、津波の被害が大きくなりやすいのはなぜ?', hint: '湾の形が、奥に行くほどどうなっているかを考えます。', steps: ['リアス海岸の湾は、湾口が広く、奥へ行くほどせまくなる形をしている。', '湾に入った津波は、せまくなる湾の奥に集められる。', '水の行き場がなくなるので、湾の奥で波が高くなる。'], a: '湾口が広く奥がせまいV字形の湾のため、入りこんだ津波が湾の奥で高くなるから。', check: '同じ津波でも、湾の奥にある集落ほど浸水の高さが大きくなる記録が多いことと合っているか確かめます。' }
        ] }
    ],
    faq: [
      ['安定陸塊にも山はあるの?', '大部分は平原や台地ですが、まったく起伏がないわけではありません。長い侵食で、かたい岩の部分が残った丘などがあります。\nただし、新期造山帯のような高くけわしい山脈はほとんどなく、地震や火山も少ないのが特徴です。'],
      ['日本の平野の多くが扇状地や三角州なのはなぜ?', '日本は山がちで、川が短く急流です。大雨のたびに山から大量の土砂が運ばれ、谷口に扇状地、河口に三角州をつくってきました。\n日本の平野の多くは、こうした川の堆積でできた【沖積平野】です。'],
      ['砂州と砂嘴はどうちがうの?', '砂嘴は、砂が海に向かってくちばしのように突き出た地形で、先が陸地につながっていません。\n砂州は、砂嘴がさらにのびて湾の入り口をほとんどふさいだり、対岸や島に近づいたりした地形です。天橋立が代表例です。']
    ],
    terms: [['内的営力', '地殻変動や火山活動など、地球内部から地形をつくる力'], ['外的営力', '風化・侵食・運搬・堆積など、地表で地形を変える力'], ['海溝', 'プレートがしずみこむ所にできる、海底の深い溝'], ['安定陸塊', '先カンブリア時代に造山運動を受け、その後は安定している平らな陸地'], ['扇状地', '川が谷口に土砂を積もらせてできた扇形の地形'], ['自然堤防', '洪水で運ばれた砂が川岸に積もってできた微高地'], ['リアス海岸', 'V字谷が沈水してできた、入り組んだ海岸'], ['フィヨルド', '氷河がつくったU字谷が沈水してできた細長い湾']],
    miss: ['扇央が水田だと考えてしまう。扇央は水はけがよすぎて水が地下にしみこむので、畑や果樹園。水田と集落は、わき水が出る扇端と覚える。', 'リアス海岸とフィヨルドのもとになった谷を逆に覚える。リアス=川=V字谷、フィヨルド=氷河=U字谷と、「何がけずったか」をセットにする。', '古期造山帯と新期造山帯の資源を取りちがえる。古生代の植物が石炭になったので、石炭は古期造山帯、と時代と結びつけて覚える。', '自然堤防と後背湿地の高さを逆にする。洪水のとき粒の大きい砂は川の近くにすぐ積もるので、川ぞいの方が高い、と理由で考える。'],
    sum: ['地形は内的営力(起伏を大きくする)と外的営力(起伏を小さくする)でつくられる。', 'プレートの境界は広がる・せばまる・ずれるの3種類。せばまる境界に海溝・弧状列島・大山脈ができる。', '大地形は、安定陸塊(鉄鉱石)・古期造山帯(石炭)・新期造山帯(地震・火山)に分けられる。', '扇状地は扇央が畑・果樹園、扇端が集落・水田。氾濫原は自然堤防が集落、後背湿地が水田。', '海岸は沈水するとリアス海岸・フィヨルド・エスチュアリー、離水すると海岸平野・海岸段丘になる。'],
    next: '次は「農業の立地と形態・食料問題(gg_agri)」へ進みましょう。気候と地形が、どのような農業を生み出しているのかを学びます。地形と災害の関係は「自然災害と防災(gg_disaster)」でさらにくわしく扱います。'
  };

  // ===== 農業の立地と形態・食料問題 =====
  L.gg_agri = {
    goal: '農業の立地を自然条件と社会条件から説明でき、世界の主な農業の形態を気候や地域と結びつけて区別し、食料問題の原因と対策を考えられるようになる。',
    intro: 'スーパーに並ぶバナナはフィリピン産、牛肉はオーストラリア産、小麦粉の原料はアメリカやカナダ産のことがよくあります。なぜその作物が、その国でつくられているのでしょうか。それは、作物に合った気候や土地があり、さらに市場への近さや技術、資本(お金)などの条件がそろっているからです。この単元では、世界の農業を「どこで・何を・どのように」つくっているかで整理し、食料がかたよって分布する問題まで考えます。',
    pre: '前の単元で学んだ気候区分は、農業を考えるときの土台です。たとえば、稲は高温多雨の地域、小麦は比較的すずしく雨の少ない地域、オリーブやぶどうは夏に乾燥する地中海性気候の地域に向いています。\n作物が育つには、気温・降水量・日照・土壌などの条件が必要です。気温が低すぎたり雨が少なすぎたりすると、【灌漑】(川や地下水から人工的に水を引くこと)などの工夫がなければ農業はできません。\n農業には、自分たちが食べるためにつくる【自給的】なものと、売るためにつくる【商業的】なものがあります。\n生産量などの統計は年によって変わります。この単元では、変わりにくい順位や傾向だけをとりあげます。たとえば、米の生産量は中国とインドが世界の1・2位をしめ、とうもろこしはアメリカが世界最大の生産国です。',
    secs: [
      { h: '農業の立地条件:自然条件と社会条件', t: 'ある作物がどこでつくられるかは、【自然条件】と【社会条件】の組み合わせで決まります。\n自然条件は、気温・降水量・地形・土壌などです。作物にはそれぞれ栽培できる範囲(【栽培限界】)があります。たとえば、農作物の栽培がほぼできなくなる寒さの限界(寒冷限界)や、灌漑なしでは農業ができない乾燥の限界(乾燥限界)があります。\n社会条件は、市場(消費地)までの距離、交通、農業技術、資本、労働力、国の政策などです。\nなぜ社会条件が大切なのでしょうか。自然条件がよくても、市場まで遠く運ぶ費用が高ければ、新鮮さが必要な野菜は売れません。逆に、灌漑や品種改良などの技術があれば、自然条件の厳しい土地でも農業ができます。\nたとえば、乾燥したアメリカのグレートプレーンズでは、地下水をくみ上げて円形に散水する【センターピボット方式】の灌漑によって、とうもろこしや小麦が大規模に栽培されています。ただし、地下水の枯渇が心配されています。',
        key: '農業の立地=自然条件(気温・降水・地形・土壌)+社会条件(市場・交通・技術・資本・政策)。' },
      { h: 'チューネンの孤立国:市場からの距離と農業', t: '19世紀のドイツの経済学者【チューネン】は、市場からの距離と輸送費によって、農業の種類が変わることを説明しました。\n彼は、自然条件がどこでも同じで、中心に都市(市場)が1つだけある平野(孤立国)を考えました。すると、都市を中心に、農業の種類が同心円状に並ぶことになります。\nなぜでしょうか。都市に近い土地は輸送費が安く、地代(土地の値段)が高いので、せまい土地で多くの利益をあげる作物が有利です。だから、新鮮さが大切でいたみやすい【野菜や牛乳】は都市のすぐ近くでつくります。\n都市から離れるほど輸送費がかかるので、輸送しやすい穀物や、広い土地を使う牧畜が有利になります。いちばん外側は【牧畜】です。家畜は自分で歩いて市場まで運べたからです。\nチューネンの時代は、燃料や建築材料として木材が重要で、重くて運びにくかったので、【林業】が都市の近くに位置しています。\n現実には地形や交通網があるので同心円にはなりませんが、「市場からの距離が農業の形を決める」という考え方は今も使えます。大都市の近くで野菜や花を育てる【近郊農業】がその例です。',
        key: '市場に近いほど集約的(野菜・牛乳)、遠いほど粗放的(穀物・牧畜)。輸送費と地代が決め手。',
        fig: THUNEN,
        ex: [{ q: '交通が発達して冷蔵輸送ができるようになると、チューネンの同心円はどのように変わると考えられる?', hint: '輸送費と新鮮さの問題が小さくなると、何が起きるでしょう。', steps: ['チューネンのモデルでは、輸送費といたみやすさが、作物ごとの最適な場所を決めていた。', '高速道路や冷蔵トラック・航空輸送が発達すると、遠くからでも新鮮な野菜や花を短時間で運べる。', 'そのため、市場から遠い地域でも、気候などの条件を生かして野菜をつくれるようになる。', '日本では、高知県や宮崎県の促成栽培や、長野県の高原野菜(抑制栽培)が大都市に出荷されている。'], a: '輸送の制約が小さくなるので、同心円がくずれ、市場から遠い地域でも気候を生かした野菜や花の栽培が行われるようになる。', check: '遠くの産地の野菜が、季節をずらして大都市の市場に出回っている例があるかを確かめます。' }] },
      { h: '自給的農業:遊牧・焼畑・アジアの稲作', t: '自分たちの生活のための食料をつくる農業を【自給的農業】といいます。\n【遊牧】は、乾燥地や寒冷地で、水や草を求めて家畜とともに移動する牧畜です。モンゴルでは羊・やぎ・馬などを飼い、組み立て式の住居【ゲル】で暮らします。西アジアや北アフリカではらくだや羊、チベット高原ではヤク、北極圏ではトナカイが飼われています。\n【焼畑農業】は、熱帯の森林や草原を焼き、その灰を肥料にして、キャッサバやタロいも・ヤムいもなどのいも類を栽培する農業です。熱帯の土壌はやせているので数年で地力が落ち、耕地を移していきます。森林が回復する前に焼くと、森林破壊につながります。\n【オアシス農業】は、乾燥地のオアシスで、わき水や地下水路(イランのカナート、北アフリカのフォガラなど)の水を使って、なつめやし・小麦・綿花などを育てる農業です。\n【集約的稲作農業】は、夏の季節風(モンスーン)で高温多雨になる東アジア・東南アジア・南アジアで行われています。せまい土地に多くの労働力をつぎこみ、単位面積あたりの収穫量を多くします。【集約的畑作農業】は、稲作には雨が少ない中国の華北やインドのデカン高原などで、小麦・綿花・大豆などをつくる農業です。',
        key: '遊牧(乾燥・寒冷地で移動)、焼畑(熱帯・いも類・移動耕作)、オアシス農業(乾燥地の水)、集約的稲作(モンスーンアジア)。',
        ex: [{ q: 'アジアの稲作地域が、東アジア・東南アジア・南アジアの沿岸部や大河の流域に集中しているのはなぜ?', hint: '稲が育つのに必要な条件と、季節風の関係を考えます。', steps: ['稲は、生育期に高温で、水を大量に必要とする作物である。', 'モンスーンアジアでは、夏に海からの湿った季節風がふき、高温多雨になる。', '大河の下流の平野や三角州は平らで水を引きやすく、水田をつくりやすい。', '稲は単位面積あたりで多くの人口を養えるので、これらの地域は人口も多い。'], a: '夏の季節風で高温多雨になり、大河の流域の平野で水田に水を引きやすいから。', check: '乾燥帯に近いインド北西部やパキスタンでは、灌漑によって稲作が行われていることと矛盾しないか確かめます。' }] },
      { h: '商業的農業:混合農業・酪農・園芸農業・地中海式農業', t: '売ることを目的とする農業を【商業的農業】といいます。ヨーロッパで発達しました。\n中世ヨーロッパでは、耕地を冬作物(小麦など)・夏作物(大麦など)・休閑地(休ませる土地)の3つに分けて順番に使う【三圃式農業】が行われました。これが発展して、作物の栽培と家畜の飼育を組み合わせる【混合農業】になりました。飼料作物(とうもろこしなど)で豚や牛を育て、肉を売ります。ドイツやフランス、アメリカのコーンベルトなどに見られます。\n【酪農】は、乳牛を飼い、牛乳やバター・チーズを生産する農業です。すずしく、穀物栽培に向かない土地で行われます。北海沿岸のデンマークや、氷河の影響でやせた土地の多い五大湖周辺、北海道などが代表例です。\n【園芸農業】は、大都市への出荷を目的に、野菜・果物・花を集約的に栽培する農業です。オランダのチューリップ栽培などが有名です。\n【地中海式農業】は、地中海性気候の地域で、夏の乾燥に強いオリーブ・ぶどう・柑橘類などの樹木作物をつくり、雨の降る冬に小麦を育てる農業です。羊ややぎの飼育も組み合わせます。地中海沿岸のほか、アメリカのカリフォルニア州、チリ中部、オーストラリア南部などにも見られます。',
        key: '混合農業=作物+家畜(肉)、酪農=冷涼地で乳製品、園芸農業=都市近郊で野菜・花、地中海式=夏はオリーブ・ぶどう、冬は小麦。',
        ex: [{ q: '地中海式農業で、夏にオリーブやぶどう、冬に小麦をつくるのはなぜ?気候と結びつけて説明しよう。', hint: '地中海性気候は、いつ雨が降るでしょうか。', steps: ['地中海性気候は、夏は亜熱帯高圧帯におおわれて高温で乾燥し、冬は偏西風の影響で雨が降る。', 'オリーブやぶどうは、根を深くはり、葉から水分が失われにくいので、夏の乾燥に強い。', '小麦は冬の雨を使って育ち、乾燥する初夏に収穫できる。', 'このように、雨の時期に合わせて作物を組み合わせている。'], a: '夏は乾燥するので乾燥に強い樹木作物をつくり、雨の降る冬にその水を使って小麦を育てるから。', check: '南半球の地中海性気候の地域(チリ中部など)でも、ぶどうの栽培とワインの生産がさかんであることと一致するか確かめます。' }] },
      { h: '企業的農業とプランテーション', t: '広い土地で大型機械を使い、少ない人手で大量に生産して世界に輸出する農業を【企業的農業】といいます。新大陸(南北アメリカ・オーストラリアなど)で発達しました。\n【企業的穀物農業】は、小麦などを大規模に栽培する農業です。アメリカのグレートプレーンズ、カナダの中南部、アルゼンチンの【パンパ】、オーストラリア南東部などが代表的な産地です。\n【企業的牧畜】は、広い牧場で肉牛や羊を大規模に飼う牧畜です。アメリカでは、出荷前の牛にとうもろこしなどの濃厚飼料をあたえて太らせる肥育場(【フィードロット】)も見られます。オーストラリアやニュージーランドでは羊の飼育がさかんです。\n【プランテーション農業】は、熱帯や亜熱帯で、主に植民地時代に欧米の資本によって開かれた大農園で、輸出用の作物を単一栽培する農業です。天然ゴム(タイ・インドネシア)、油やし(インドネシア・マレーシア)、コーヒー(ブラジル・ベトナム)、カカオ(コートジボワール・ガーナ)、茶、バナナ、さとうきびなどがあります。\n企業的な農業の背景には、種子・肥料・農業機械・加工・流通までを手がける【アグリビジネス】や、世界の穀物の取引に大きな影響力をもつ【穀物メジャー】(大規模な穀物商社)があります。',
        key: '企業的穀物農業(グレートプレーンズ・パンパなど)、企業的牧畜(フィードロット・羊)、プランテーション(熱帯の輸出用作物の単一栽培)。',
        flow: { title: '農業の形態(ホイットルセーの区分をもとに整理)', cols: 3, head: ['自給的農業', '商業的農業', '企業的農業'], rows: [
          [['遊牧', 'o', 1, '乾燥地・寒冷地'], ['混合農業', 'b', 1, '作物+家畜'], ['企業的穀物農業', 'r', 1, '小麦・大規模']],
          [['焼畑農業', 'o', 1, '熱帯・いも類'], ['酪農', 'b', 1, '冷涼地・乳製品'], ['企業的牧畜', 'r', 1, '牛・羊']],
          [['オアシス農業', 'o', 1, '乾燥地の水'], ['園芸農業', 'b', 1, '都市近郊'], ['プランテーション', 'r', 1, '熱帯の輸出作物']],
          [['集約的稲作・畑作', 'o', 1, 'モンスーンアジアなど'], ['地中海式農業', 'b', 1, 'オリーブ・ぶどう'], ['(新大陸で発達)', 'e']]
        ], legend: [['o', '自分たちの食料が中心'], ['b', 'ヨーロッパで発達'], ['r', '大規模・輸出向け']] },
        ex: [{ q: '次の説明にあてはまる農業の形態は?「アルゼンチンの温帯草原で、広い農地に大型機械を使って小麦を大規模に栽培し、輸出している。」', hint: '「大型機械」「大規模」「輸出」がキーワードです。', steps: ['アルゼンチンの温帯草原はパンパとよばれる。', '大型機械を使い、少ない人手で大規模に栽培している。', '作物は小麦で、主に輸出向けである。', 'これらは企業的農業のうち、穀物を中心とするものにあたる。'], a: '企業的穀物農業', check: 'アメリカのグレートプレーンズやカナダ中南部など、新大陸の他の小麦地帯と同じ特徴か確かめます。' }] },
      { h: '世界の食料問題と日本の食料', t: '世界全体では、人口を養えるだけの穀物が生産されているといわれます。それなのに、なぜ飢えに苦しむ人がいるのでしょうか。理由は、食料が【かたよって】分布しているからです。\n先進国では、穀物の多くが家畜の飼料に使われ、肉の生産にまわされています。牛肉1kgをつくるには、その何倍もの量の飼料用穀物が必要です。また、まだ食べられるのに捨てられる【食品ロス】も問題になっています。\n一方、アフリカのサハラ砂漠の南の地域(サヘル)などでは、干ばつや紛争、貧困によって食料が不足しています。人口の増加に食料生産が追いつかない地域もあります。\nアジアでは1960年代から、高収量品種の導入や灌漑・化学肥料の普及によって穀物の生産を大きく増やす【緑の革命】が進みました。インドなどで食料の増産に成功しましたが、灌漑設備や肥料を買える豊かな農家とそうでない農家の格差が広がるなどの課題も生まれました。\n日本の【食料自給率】(カロリーベース)は、食生活の洋風化で米の消費が減り、輸入にたよる小麦や飼料を使う肉・油の消費が増えたため長期的に低下し、近年は4割程度です。主要な先進国の中でも低い水準です。\n食料の輸送による環境への負荷を表す指標に【フードマイレージ】(食料の重さ×輸送距離)があります。近くでとれたものを近くで消費する【地産地消】は、フードマイレージを小さくする取り組みの1つです。',
        key: '食料問題の根本は「量」より「かたより」。日本の自給率(カロリーベース)は約4割で低い。フードマイレージ=重さ×距離。',
        ex: [
          { q: '2tの小麦を10000km離れた国から輸入する場合と、200km離れた国内の産地から運ぶ場合のフードマイレージ(t・km)をそれぞれ求め、何倍ちがうか答えよう。', hint: 'フードマイレージ=重さ(t)×輸送距離(km)です。', steps: ['輸入の場合:2×10000=20000t・km。', '国内の場合:2×200=400t・km。', '20000÷400=50。'], a: '輸入は20000t・km、国内は400t・kmで、50倍ちがう', check: '重さが同じなので、距離の比 10000÷200=50 とも一致します。' },
          { q: '緑の革命によってインドの穀物生産が増えたにもかかわらず、農村の貧困がすべて解決したわけではないのはなぜ?', hint: '高収量品種を育てるには、何が必要だったでしょうか。', steps: ['緑の革命の高収量品種は、たくさんの水と化学肥料をあたえることで多く収穫できる。', '灌漑設備や肥料、農薬を買うには資金が必要である。', '資金のある大きな農家は生産を増やせたが、資金のない小さな農家は導入が難しかった。', 'そのため、農家の間の経済格差が広がり、土地を手放す農民も出た。'], a: '高収量品種には灌漑や化学肥料が必要で、それを用意できる豊かな農家とできない貧しい農家の間で格差が広がったから。', check: '緑の革命の成果(生産増)と課題(格差・環境への負担)を分けて説明できているかを確かめます。' }
        ] }
    ],
    faq: [
      ['混合農業と酪農は、どちらも家畜を飼うけれど何がちがうの?', '混合農業は、作物の栽培と家畜の飼育を組み合わせて、主に肉を売る農業です。\n酪農は、乳牛を飼って牛乳・バター・チーズなどの乳製品を売る農業で、穀物栽培に向かない冷涼な地域で行われることが多い点がちがいます。'],
      ['プランテーションの国は、なぜ経済が不安定になりやすいの?', '特定の作物の輸出にたよる【モノカルチャー経済】になりやすいからです。\nその作物の国際価格が下がったり、天候不順で不作になったりすると、国の収入が大きく減ってしまいます。そのため、作物の種類を増やしたり工業を育てたりする取り組みが進められています。'],
      ['日本の食料自給率が低いと、何が問題なの?', '輸出国の不作や紛争、輸送の混乱などで輸入が止まると、食料が手に入りにくくなるおそれがあります。\nそのため、国内の農業を守り育てることや、輸入先を分散させることが大切だと考えられています。']
    ],
    terms: [['灌漑', '川や地下水などから人工的に農地へ水を引くこと'], ['センターピボット方式', '地下水をくみ上げ、回転するスプリンクラーで円形に散水する灌漑方式'], ['混合農業', '作物の栽培と家畜の飼育を組み合わせた商業的農業'], ['酪農', '乳牛を飼い、牛乳や乳製品を生産する農業'], ['プランテーション', '熱帯などで輸出用作物を大規模に単一栽培する農園'], ['アグリビジネス', '種子・肥料・機械から加工・流通までを手がける農業関連産業'], ['緑の革命', '高収量品種の導入などで、アジアなどの穀物生産を大きく増やした改革'], ['フードマイレージ', '食料の重さ×輸送距離で表す、輸送による環境負荷の指標']],
    miss: ['地中海式農業の季節を逆にする。地中海性気候は夏に乾燥するので、夏は乾燥に強い樹木作物、冬は小麦、と気候からたどる。', '混合農業と酪農を混同する。混合農業は「作物+家畜で肉」、酪農は「乳牛で乳製品」と、売るものに注目して区別する。', 'チューネンのモデルで、牧畜が都市の近くにあると考える。広い土地が必要で、家畜は自分で歩いて運べたので、いちばん外側と理由で覚える。', '食料問題を「世界全体で食料が足りない」とだけ考える。生産はあっても、地域・所得によるかたよりや、飼料・食品ロスに使われることが大きな原因だと押さえる。'],
    sum: ['農業の立地は、自然条件(気候・地形・土壌)と社会条件(市場・技術・資本・政策)で決まる。', 'チューネンは、市場からの距離と輸送費によって農業の種類が同心円状に変わると説明した。', '自給的農業には遊牧・焼畑・オアシス農業・集約的稲作などがある。', '商業的農業は混合農業・酪農・園芸農業・地中海式農業、企業的農業は企業的穀物農業・企業的牧畜・プランテーション。', '食料問題の中心は分布のかたより。日本の食料自給率(カロリーベース)は約4割と低い。'],
    next: '次は「資源・エネルギーと工業の立地(gg_industry)」へ進みましょう。農業と同じように、「なぜそこで生産するのか」を、資源の分布や輸送費から考えます。'
  };

  var PYRAMID = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="人口ピラミッドの3つの型。すそ広がりの富士山型、上部だけがせまいつりがね型、下部がせまく中央がふくらむつぼ型"><line x1="8" y1="110" x2="212" y2="110" class="ax"/><path d="M40 18 L12 110 L68 110 Z" class="tr"/><path d="M102 18 L86 48 L84 110 L136 110 L134 48 L118 18 Z" class="tr"/><path d="M174 18 L160 44 L154 74 L164 110 L196 110 L206 74 L200 44 L186 18 Z" class="tr"/><text x="8" y="14">高齢</text><text x="16" y="126">富士山型</text><text x="83" y="126">つりがね型</text><text x="164" y="126">つぼ型</text><text x="22" y="143">多産多死</text><text x="88" y="143">少産少死</text><text x="152" y="143">少子高齢化</text></svg>';

  // ===== 資源・エネルギーと工業の立地 =====
  L.gg_industry = {
    goal: '資源・エネルギーの分布のかたよりと利用の変化を説明でき、工業の立地を輸送費・労働力・市場・集積などの条件から説明でき、グローバル化による工業の変化を理解できるようになる。',
    intro: 'スマートフォン1台には、レアメタルとよばれる珍しい金属が何種類も使われています。その原料はアフリカや南アメリカの鉱山で掘られ、部品はアジアのいくつもの国でつくられ、組み立てはまた別の国で行われます。なぜ、こんなに多くの国をまたいで生産するのでしょうか。それは、資源のある場所、人件費の安い場所、技術のある場所、売れる場所がそれぞれちがうからです。この単元では、資源とエネルギーの分布、そして工場がどこにつくられるかを決める条件を学びます。',
    pre: '前の単元で学んだように、大地形と資源には関係があります。安定陸塊には鉄鉱石、古期造山帯には石炭が多く分布します。原油はペルシア湾岸に特に多く埋蔵されています。\n【一次エネルギー】は、石炭・石油・天然ガス・水力・原子力・太陽光など、自然から得られるままのエネルギーです。これを変換してつくる電気やガソリンは【二次エネルギー】です。\n【化石燃料】(石炭・石油・天然ガス)は、大昔の生物の遺骸が地中で長い時間をかけて変化したもので、使えばなくなり、燃やすと二酸化炭素を出します。これに対して、太陽光・風力・水力・地熱・バイオマスなど、くり返し使えるエネルギーを【再生可能エネルギー】といいます。\n産業は、農林水産業の【第1次産業】、鉱業・製造業・建設業の【第2次産業】、商業・サービス業などの【第3次産業】に分けられます。工業は第2次産業の中心です。',
    secs: [
      { h: '資源の分布はかたよっている', t: 'なぜ資源をめぐる問題が起きやすいのでしょうか。資源は地球上に均等にあるのではなく、特定の地域に【かたよって】分布しているからです。\n【石油(原油)】は、サウジアラビア・イラン・イラクなどの【ペルシア湾岸】に、世界の埋蔵量の大きな割合が集中しています。そのほか、ベネズエラ、ロシア、アメリカ、カナダなどにも多くあります。\n【石炭】は比較的広く分布し、中国・インド・アメリカ・オーストラリア・ロシアなどで産出します。生産量は中国が世界最大で、インドがそれに次ぎます。\n【鉄鉱石】はオーストラリアやブラジルが大産地で、日本の輸入先もこの2か国が上位です。【銅鉱】はチリが世界最大の産出国です。\n【レアメタル】(希少金属)は、コバルト・リチウム・レアアース(希土類)など、量が少なかったり取り出しにくかったりする金属です。電子機器や電気自動車の電池に欠かせませんが、産出国がさらに少数の国にかたよっています。使い終わった電子機器にふくまれる金属を回収して再利用する【都市鉱山】の考え方も広がっています。\n資源をもつ国は、かつて欧米の大企業(石油メジャーなど)に開発をまかせていましたが、第二次世界大戦後、自国の資源は自国で管理すべきだという【資源ナショナリズム】が高まりました。1960年には産油国が【OPEC(石油輸出国機構)】を結成しました。',
        key: '石油はペルシア湾岸、鉄鉱石はオーストラリア・ブラジル、銅はチリ。資源のかたよりが資源ナショナリズムや国際問題を生む。' },
      { h: 'エネルギー利用の移り変わり', t: '18世紀後半の産業革命以降、蒸気機関の燃料として【石炭】が主要なエネルギーになりました。\n1960年代になると、中東などで安い石油が大量に生産されるようになり、主要なエネルギーが石炭から【石油】へと急速に移りました。これを【エネルギー革命】といいます。石油は液体で運びやすく、燃料だけでなくプラスチックなどの原料にもなるからです。\n1973年と1979年には、中東の情勢を背景に原油価格が急上昇する【石油危機】(オイルショック)が起き、石油の輸入にたよる国々は大きな打撃を受けました。そこで各国は、省エネルギーを進めるとともに、天然ガス・原子力などへエネルギー源を分散させました。\n【天然ガス】は、燃やしたときの二酸化炭素の排出が石炭や石油より少なく、冷やして液体にした【LNG(液化天然ガス)】として専用の船で運ばれます。\n国ごとの発電の内訳には、自然条件や政策がよく表れます。山が多く川の豊かなノルウェーやカナダ、ブラジルでは【水力】の割合が高く、フランスは【原子力】の割合が高い国です。火山の多いアイスランドでは【地熱】がさかんで、デンマークは【風力】の利用で知られます。日本は2011年の東日本大震災のあと原子力発電が大きく減り、火力発電の割合が高くなりました。\n近年は地球温暖化を防ぐため、太陽光や風力などの再生可能エネルギーを増やす動きが世界中で進んでいます。ただし、天候によって発電量が変わるという課題があります。',
        key: '石炭→石油(1960年代のエネルギー革命)→石油危機(1973・1979)で分散→再生可能エネルギーの拡大。発電の内訳は自然条件と政策で決まる。',
        ex: [{ q: '次のA〜Cは、ノルウェー・フランス・日本のいずれかの発電の特徴である。それぞれどの国?\nA:原子力の割合が最も高い。\nB:水力の割合が非常に高い。\nC:火力の割合が高い。', hint: '各国の自然条件と、エネルギー政策を思い出しましょう。', steps: ['ノルウェーは、氷河がけずった急な地形と豊富な降水・雪どけ水があり、水力発電に適している。だからB。', 'フランスは、石油危機のあと原子力発電を国の政策として大きく進めてきた。だからA。', '日本は、2011年の東日本大震災のあと原子力発電所の多くが停止し、輸入した石炭やLNGによる火力発電の割合が高い。だからC。'], a: 'A:フランス B:ノルウェー C:日本', check: '「水力=山がちで水の多い国、原子力=政策で推進した国、火力=燃料を輸入する国」という見方で、ブラジルやカナダ(水力が多い)にも当てはまるか確かめます。' }] },
      { h: '工業の立地条件:何にお金がかかるか', t: '工場をどこに建てるかは、生産にかかる費用が最も安くなる場所を選ぶ、という考え方で説明できます。ドイツの【ウェーバー】は、特に【輸送費】に注目して工業の立地を説明しました。\n【原料指向型】:原料が重く、製品にすると重さが大きく減る工業は、原料の産地の近くに立地します。たとえばセメント工業は、原料の石灰石の産地の近くに工場があります。\n【市場指向型】:どこでも手に入る原料(水など)を使い、製品が重かったりいたみやすかったりする工業は、消費地(市場)の近くに立地します。ビールや清涼飲料水が代表例です。また、流行や情報が大切な印刷・出版業も大都市に集まります。\n【労働力指向型】:多くの人手が必要な工業は、賃金の安い労働力が豊富な地域に立地します。衣類の縫製や電気機械の組み立てなどです。\n【臨海指向型】:原料や燃料を輸入にたよる工業は、港のある臨海部に立地します。日本の鉄鋼業や石油化学工業がその例です。\n【臨空港指向型】:集積回路(IC)のように小さく軽いのに高価な製品は、航空機で運んでも採算がとれるので、空港や高速道路の近くに立地します。\n【集積指向型】:自動車工業のように多くの部品を必要とする工業は、関連工場が近くに集まる(集積する)と輸送費や情報交換の面で有利になります。',
        key: '原料が重い→原料産地、製品が重い・普遍原料→市場、人手が多い→安い労働力、輸入原料→臨海、軽くて高価→空港、部品が多い→集積。',
        flow: { title: '工業の立地の型', cols: 3, head: ['型', '理由', '例'], rows: [
          [['原料指向型', 'k'], ['原料が重く製品で軽くなる', 'k'], ['セメント', 'k']],
          [['市場指向型', 'b'], ['製品が重い・情報が大切', 'b'], ['ビール・出版', 'b']],
          [['労働力指向型', 'g'], ['人手が多く必要', 'g'], ['衣類・機械の組立', 'g']],
          [['臨海指向型', 'sea'], ['原料・燃料を輸入', 'sea'], ['日本の鉄鋼・石油化学', 'sea']],
          [['臨空港指向型', 'o'], ['軽くて高価', 'o'], ['IC(集積回路)', 'o']],
          [['集積指向型', 'r'], ['部品・関連工場が多い', 'r'], ['自動車', 'r']]
        ] },
        ex: [
          { q: '原料10tから製品2tができる工業がある。原料産地Aと市場Bは100km離れており、輸送費は原料・製品とも1tを1km運ぶごとに同じ金額とする。工場をAとBのどちらに建てると輸送費が安い?', hint: 'A、Bそれぞれに建てた場合に「何を何t運ぶか」を考えます。', steps: ['Aに建てた場合:製品2tをBまで100km運ぶので、2×100=200(t・km)分の輸送費。', 'Bに建てた場合:原料10tをAから100km運ぶので、10×100=1000(t・km)分の輸送費。', '200<1000なので、Aに建てた方が輸送費が安い。'], a: '原料産地A(輸送費はBに建てた場合の5分の1)', check: '原料の方が重い(重さが減る)工業は原料指向型になる、というウェーバーの考え方と一致します。' },
          { q: '日本の鉄鋼業の工場が、北九州や京浜・阪神などの臨海部に多いのはなぜ?', hint: '鉄鋼の原料である鉄鉱石と石炭は、どこから来るでしょうか。', steps: ['鉄鋼業の主な原料は、鉄鉱石と石炭(原料炭)である。', '日本は、これらのほとんどをオーストラリアやブラジルなどから船で輸入している。', '大型船が着く港のそばに工場があれば、原料を陸上で運ぶ費用がかからない。', 'さらに、製品の鉄鋼も船で国内外へ出荷しやすい。'], a: '原料の鉄鉱石と石炭をほぼすべて輸入しており、大型船で運びこめる臨海部が輸送に有利だから。', check: '同じく原油を輸入する石油化学コンビナートも、臨海部に立地していることと一致するか確かめます。' }
        ] },
      { h: '工業の発展と立地の変化', t: '工業の中心は、時代とともに移り変わってきました。18世紀後半のイギリスの産業革命では、綿工業などの【軽工業】が発達し、19世紀以降は鉄鋼・機械・化学などの【重化学工業】、20世紀後半からは電子機器や情報通信などの【先端技術産業】(ハイテク産業)が成長しました。\n鉄鋼業の立地の変化は分かりやすい例です。かつては大量の石炭を燃料として使ったので、ドイツの【ルール地方】やアメリカのピッツバーグのように、炭田の近くに工場がつくられました。技術の進歩で石炭の使用量が減り、原料を輸入にたよるようになると、日本やヨーロッパでは臨海部に新しい製鉄所がつくられるようになりました。\n1970年代以降、先進国では賃金が上がり、新しく工業化した国や地域との競争が激しくなりました。アジアでは、韓国・台湾・香港・シンガポールが急速に工業化し、【NIEs(新興工業経済地域)】とよばれました。その後、ASEAN諸国や中国、インドなどが続きました。中国は外国企業の工場を多く受け入れ、「世界の工場」とよばれるようになりました。\n先進国の企業は、人件費の安い国へ工場を移し、国内では研究開発や本社機能に力を入れるようになりました。このように生産拠点が海外へ移り、国内の製造業や雇用が減る現象を【産業の空洞化】といいます。\n現在では、複数の国に拠点をもつ【多国籍企業】が、部品の生産・組み立て・販売をいくつもの国に分けて行っています(【国際分業】)。原料の調達から販売までのつながりを【サプライチェーン】といい、災害や感染症で一部が止まると、世界中の生産に影響が出ることもあります。',
        key: '軽工業→重化学工業→先端技術産業。生産拠点が人件費の安い国へ移り、先進国では産業の空洞化が起きた。',
        chain: { title: '産業の空洞化が起こるまで', items: [
          ['背景', '先進国で賃金が上がり、通貨の価値も上がる', '日本では1985年以降の円高'],
          ['企業の行動', '人件費の安いアジアなどへ工場を移す', '多国籍企業の国際分業'],
          ['結果', '国内の工場が減り、製造業の雇用が減る', '産業の空洞化'],
          ['その後', '国内では研究開発・高付加価値の製品・サービス業へ', '新興国では工業化が進む']] },
        ex: [{ q: '1985年以降の円高が、日本の製造業の海外進出をうながしたのはなぜ?', hint: '円高になると、日本でつくった製品を海外で売るときの値段はどうなるでしょう。', steps: ['円高とは、外国の通貨に対して円の価値が上がることである。', '円高になると、日本でつくった製品をドルなどで売るときの値段が上がり、輸出で不利になる。', '一方、海外の土地や労働力は、円に換算すると安く使えるようになる。', 'そこで企業は、人件費の安いアジアなどに工場を移して生産するようになった。'], a: '円高で日本からの輸出が不利になる一方、海外で生産する費用が円に換算すると安くなったから。', check: 'この時期以降、自動車や電気機械の海外生産が増えたことと結びついているか確かめます。' }] },
      { h: '世界の主な工業地域', t: '【アメリカ合衆国】:五大湖の周辺は、鉄鉱石や石炭、水運にめぐまれ、鉄鋼業や自動車工業(デトロイト)が発達しました。しかし、1970年代以降は国際競争で工業がおとろえ、北東部から中西部は【ラストベルト】(さびついた地帯)ともよばれます。かわって、北緯37度付近より南の【サンベルト】で、温暖な気候、安い土地と労働力、税の優遇などを背景に、航空宇宙産業やエレクトロニクス産業が発達しました。サンフランシスコ郊外の【シリコンヴァレー】は、ICT産業の世界的な中心地です。\n【ヨーロッパ】:イギリス南部からベネルクス、ドイツのライン川流域、スイスを経て北イタリアにいたる地域は、工業や人口が集中し、その形から【青いバナナ】(ブルーバナナ)とよばれます。航空機の生産では、複数の国の企業が部品を分担し、フランスのトゥールーズなどで組み立てる国際分業が行われています。\n【中国】:1979年以降の【改革・開放政策】で、沿海部のシェンチェン(深圳)などに外国の資本や技術を受け入れる【経済特区】を設けました。沿海部は急速に工業化しましたが、内陸部との経済格差が課題になっています。\n【インド】:英語を話せる技術者が多く、アメリカとの時差を利用して業務を引きつげることなどから、南部のベンガルール(バンガロール)を中心に【ICT産業】が発達しました。\n【日本】:関東から九州北部にかけての臨海部を中心に工業地帯・地域が帯のように連なり、【太平洋ベルト】とよばれます。',
        key: 'アメリカはスノーベルト(ラストベルト)からサンベルトへ、ヨーロッパは青いバナナ、中国は経済特区から沿海部の工業化、インドはICT産業。',
        ex: [{ q: 'アメリカで工業の中心が北東部・五大湖周辺からサンベルトへ移った理由を3つ挙げよう。', hint: '気候、土地や労働力の費用、政策の面から考えます。', steps: ['気候:サンベルトは温暖で、暮らしやすく暖房費も少なくてすむ。', '費用:広く安い土地と、比較的安い労働力が得られた。', '政策:州が税の優遇などで企業を誘致した。', 'さらに、石油などの資源があり、航空宇宙・エレクトロニクスなど新しい産業が育った。'], a: '温暖な気候、安くて広い土地と労働力、税の優遇などの企業誘致(加えて資源や新しい産業の成長)。', check: '古い重工業が中心だった北東部では、設備の老朽化や国際競争で工業がおとろえたことと対比できているか確かめます。' }] }
    ],
    faq: [
      ['再生可能エネルギーが増えると、どんな課題があるの?', '太陽光や風力は、天気や時間によって発電量が大きく変わります。電気をためる蓄電池や、地域どうしで電気を融通する送電網の整備が必要です。\nまた、大規模な発電施設をつくるときに、景観や自然環境との調和が問題になることもあります。'],
      ['日本の原油の輸入先はどこが多いの?', 'サウジアラビアやアラブ首長国連邦など、中東の国々が上位をしめ、輸入の大部分を中東にたよっています。\nそのため、中東の情勢が日本のエネルギーに大きく影響します。'],
      ['工業の立地の型は、1つの工業で1つに決まるの?', '時代や技術によって変わります。鉄鋼業は、石炭を大量に使っていた時代は炭田近く(原料指向)でしたが、日本では輸入原料を使うため臨海部に立地しています。\n「その時代・その国で、何に最も費用がかかるか」を考えることが大切です。']
    ],
    terms: [['化石燃料', '石炭・石油・天然ガスなど、大昔の生物の遺骸からできた燃料'], ['再生可能エネルギー', '太陽光・風力・水力・地熱など、くり返し使えるエネルギー'], ['レアメタル', 'コバルト・リチウムなど、量が少なく取り出しにくい希少な金属'], ['資源ナショナリズム', '自国の資源は自国で管理・利用すべきだという考え方'], ['エネルギー革命', '1960年代に主要なエネルギーが石炭から石油に移ったこと'], ['産業の空洞化', '生産拠点が海外へ移り、国内の製造業や雇用が減る現象'], ['多国籍企業', '複数の国に生産・販売の拠点をもって活動する企業'], ['サンベルト', 'アメリカの北緯37度付近より南の、新しく工業が発達した地域']],
    miss: ['原料指向型と市場指向型を逆に覚える。「重い方を運ばない」と考え、原料が重ければ原料産地、製品が重ければ市場、と判断する。', '日本の鉄鋼業を原料指向型と考える。原料を輸入にたよるので、港のある臨海部に立地する臨海指向型である。', '資源の産地と大地形の結びつきを取りちがえる。鉄鉱石=安定陸塊、石炭=古期造山帯、と前の単元とセットで覚える。', 'サンベルトとスノーベルトの位置を逆にする。サン(太陽)=温暖な南部、と言葉の意味から考える。'],
    sum: ['資源の分布はかたよる。石油はペルシア湾岸、鉄鉱石はオーストラリア・ブラジル、銅はチリ。', '1960年代に石炭から石油へ(エネルギー革命)。石油危機のあとエネルギー源を分散し、今は再生可能エネルギーが拡大している。', '工業の立地は輸送費・労働力・市場・集積などで決まる(原料指向・市場指向・労働力指向・臨海指向・臨空港指向・集積指向)。', '工業の中心は軽工業→重化学工業→先端技術産業へ。生産拠点の海外移転で産業の空洞化が起きた。', 'アメリカのサンベルト、ヨーロッパの青いバナナ、中国の経済特区、インドのICT産業が重要。'],
    next: '次は「人口・都市・村落(gg_pop)」へ進みましょう。工業化が人口の動きや都市の発達とどう結びついているかを学びます。'
  };

  // ===== 人口・都市・村落 =====
  L.gg_pop = {
    goal: '世界の人口の分布と変化を人口転換と人口ピラミッドで説明でき、都市の発達と都市問題、村落の立地と形態を理由とともに説明できるようになる。',
    intro: 'ある国では、子どもが多すぎて学校が足りません。別の国では、子どもが少なすぎて学校が閉校になっています。どちらも「人口の問題」ですが、その中身は正反対です。なぜ国によってこんなにちがうのでしょうか。カギは、子どもが生まれる割合(出生率)と、人が亡くなる割合(死亡率)の変化です。この単元では、人口の変化のしくみと、人々が集まって住む都市や村落の特色を学びます。',
    pre: '【人口密度】は、人口を面積でわった値で、1km²あたりに何人が住んでいるかを表します。\n【出生率】は、1年間に生まれた子どもの数を人口1000人あたりで表した値、【死亡率】は1年間に亡くなった人の数を人口1000人あたりで表した値です。単位は‰(パーミル、1000分の1)です。出生率から死亡率を引いたものを【自然増加率】といいます。\nこれに対し、他の地域との間の人の移動(転入−転出)による人口の増減を【社会増減】といいます。\n年齢別には、0〜14歳を【年少人口】、15〜64歳を【生産年齢人口】、65歳以上を【老年人口】と分けます。\n【合計特殊出生率】は、1人の女性が一生のうちに産む子どもの数の平均を表す値です。人口を長期的に維持できる水準(人口置換水準)は約2.1とされます。',
    secs: [
      { h: '世界の人口の分布と増加', t: '人が日常的に住んでいる地域を【エクメーネ】、寒さや乾燥、高地などの厳しい環境のため、ほとんど人が住んでいない地域を【アネクメーネ】といいます。\n世界の人口は、20世紀に入って急激に増え、2022年に80億人をこえたとされます。人口の多い国は、インド、中国、アメリカ合衆国の順で、インドは2023年ごろに中国をぬいて世界最多になったと推計されています。\n人口はかたよって分布しています。アジアには世界人口の約6割が住み、特に東アジア・東南アジア・南アジアの、季節風の影響で稲作がさかんな平野は人口密度が高くなっています。稲は単位面積あたり多くの人を養えるからです。\n一方、北極圏やサハラ砂漠、アマゾンの熱帯雨林の奥地などは人口がまばらです。\n地域によって人口の増え方もちがいます。アフリカは出生率が高く、今後も人口の増加が続くと予測されています。ヨーロッパや日本、東アジアの国々では、人口の増加が止まったり減少したりしています。',
        key: '世界の人口は約80億人。人口の多い国はインド・中国・アメリカ。アジアに約6割が集中し、アフリカは今後も増加が続く。',
        ex: [{ q: 'ある国の出生率が30‰、死亡率が10‰のとき、自然増加率は何%?また、この国の人口が1000万人なら、1年間の自然増加はおよそ何人?', hint: '‰は1000分の1、%は100分の1です。', steps: ['自然増加率=出生率−死亡率=30−10=20‰。', '20‰は1000分の20なので、100分の2、つまり2%。', '1000万人×0.02=20万人。'], a: '自然増加率は2%、1年間の自然増加は約20万人', check: '1000人あたり20人増えるので、1000万人なら1万倍の20万人と別の方法でも確かめられます。' }] },
      { h: '人口転換:多産多死から少産少死へ', t: '国が経済的に発展するにつれて、出生率と死亡率は決まった順番で変化します。これを【人口転換】といいます。\n第1段階の【多産多死】では、子どもはたくさん生まれますが、医療や衛生が不十分で、乳幼児の死亡も多いので、人口はあまり増えません。\n第2段階の【多産少死】では、医療の普及、衛生状態や栄養の改善によって死亡率が先に下がります。出生率は高いままなので、人口が急激に増えます。第二次世界大戦後、アジア・アフリカ・ラテンアメリカの国々で起きた急激な人口増加は【人口爆発】とよばれます。\nなぜ出生率はすぐには下がらないのでしょうか。農村では子どもが働き手であり、親の老後を支える存在でもあるため、多くの子どもを望む考え方がすぐには変わらないからです。\n第3段階の【少産少死】では、教育の普及や女性の社会進出、都市化によって子育ての費用が上がることなどから、出生率も下がります。人口の増加はゆるやかになり、やがて止まります。\nさらに出生率が人口置換水準(約2.1)を大きく下回ると、人口は減少に向かいます。日本や韓国、多くのヨーロッパの国々がこの状態です。',
        key: '多産多死→多産少死(死亡率が先に下がり人口爆発)→少産少死。出生率が置換水準を下回ると人口減少。',
        chain: { title: '人口転換(経済の発展とともに)', items: [
          ['第1段階', '多産多死', '出生率も死亡率も高い・人口はあまり増えない'],
          ['第2段階', '多産少死', '医療・衛生の改善で死亡率が下がる・人口爆発'],
          ['第3段階', '少産少死', '教育・女性の社会進出・都市化で出生率も下がる'],
          ['その後', '少子高齢化・人口減少', '出生率が約2.1を大きく下回る国も多い']] } },
      { h: '人口ピラミッドの型を読む', t: '男女別・年齢別の人口をグラフにしたものを【人口ピラミッド】といいます。中央の縦軸が年齢(下が若く、上が高齢)、左右に男女の人数を表します。形を見れば、その国の人口転換の段階が分かります。\n【富士山型(ピラミッド型)】は、すそが広く、上に行くほどせまくなる形です。出生率も死亡率も高い(多産多死や多産少死)発展途上国に多く見られます。子どもが多く、年齢が上がるにつれて人数が少なくなっています。\n【つりがね型】は、低い年齢から中ごろまでの幅がほぼ同じで、高齢の部分だけがせまくなる形です。出生率と死亡率がともに低く、人口が安定している状態(少産少死)を表します。\n【つぼ型】は、すその部分(子ども)がせまく、中ほどがふくらんだ形です。出生率が死亡率より低くなり、少子高齢化と人口減少が進む国に見られます。現在の日本はこの型です。\n国だけでなく、地域ごとのピラミッドもあります。仕事や進学で若い世代が流入する都市では、生産年齢人口の部分が大きくふくらむ【星型】、若い世代が流出する農村では、その部分がくびれる【ひょうたん型】になります。',
        key: '富士山型=途上国(多産)、つりがね型=人口安定、つぼ型=少子高齢化。都市は星型、農村はひょうたん型。',
        fig: PYRAMID,
        ex: [{ q: 'ある国の人口ピラミッドは、0〜4歳の幅が最も広く、年齢が上がるにつれて急にせまくなっていた。この国の人口の特徴と、考えられる課題は?', hint: 'すそ広がりの形は、どの型でしょうか。', steps: ['すそが最も広く、上に行くほど急にせまくなるので、富士山型である。', '子どもが多く生まれ、高齢になるまで生きる人が少ない。つまり出生率が高く、死亡率も比較的高い。', '人口は今後も増えると考えられる。', 'そのため、食料・学校・雇用の不足や、都市への人口集中などが課題になりやすい。'], a: '出生率が高い発展途上国型(富士山型)で、人口が急増している。食料・教育・雇用の不足や都市への人口集中が課題になりやすい。', check: 'アフリカの多くの国の人口ピラミッドがこの形をしていることと合っているか確かめます。' }] },
      { h: '人口問題:途上国の人口増加と先進国の少子高齢化', t: '【発展途上国】では、急速な人口増加によって、食料・住宅・学校・仕事が足りなくなる問題が起こっています。対策として、出産の数や間隔を計画する【家族計画】の普及や、女性の教育の充実が進められています。\n中国は人口の増加をおさえるため、1979年から夫婦1組の子どもを原則1人とする【一人っ子政策】を行いました。人口の増加はおさえられましたが、急速な高齢化や男女の人口比のかたよりなどの問題が生じ、2015年に廃止が決まりました。\n【先進国】では、少子化と高齢化が同時に進む【少子高齢化】が課題です。総人口にしめる65歳以上の割合(高齢化率)が7%をこえると【高齢化社会】、14%をこえると【高齢社会】、21%をこえると【超高齢社会】とよびます。日本の高齢化率は約3割で、世界で最も高い水準です。\n少子高齢化が進むと、働き手が減り、年金や医療・介護を支える人の負担が大きくなります。日本の総人口は2000年代後半をピークに減少が続いています。\n労働力不足を補うため、外国からの労働者や移民を受け入れる国もあります。ヨーロッパでは、旧植民地や近隣の国々から多くの移民を受け入れてきましたが、文化のちがいによる摩擦などの課題もあります。',
        key: '途上国=人口増加(家族計画・女性の教育)、先進国=少子高齢化(働き手の減少・社会保障の負担)。高齢化率7%・14%・21%。',
        ex: [{ q: '総人口1200万人、65歳以上の人口が300万人の国の高齢化率は何%?また、高齢化社会・高齢社会・超高齢社会のどれにあたる?', hint: '高齢化率=65歳以上の人口÷総人口×100です。', steps: ['高齢化率=300万÷1200万×100。', '300÷1200=0.25なので、25%。', '21%をこえているので超高齢社会。'], a: '25%で、超高齢社会', check: '1200万人の4分の1が300万人なので、25%と一致します。' }] },
      { h: '都市の発達と機能', t: '人や物、情報が集まる所に都市が生まれます。昔から、川の合流点、交通路の交差点、港、山地と平野の境目(【谷口集落】)など、人や物の流れが集まる場所に都市が発達してきました。\n都市の中心部には、官公庁や大企業の本社、銀行などが集まる【中心業務地区(CBD)】があります。昼間は多くの人が集まりますが、夜間に住む人は少ないので、昼間人口が夜間人口より多くなります。\n大都市の周りには、大都市に通勤・通学する人が住む【衛星都市】(住宅都市)が広がり、大都市とともに【都市圏】をつくります。\nいくつかの大都市圏が、交通や通信で帯のように結びついた地域を【メガロポリス】といいます。アメリカ北東部のボストンからワシントンD.C.にかけての地域が代表例です。また、もともと別だった都市が拡大してつながり、1つのまとまった市街地になったものを【コナーベーション】(連接都市)といい、ドイツのルール地方などに見られます。\n世界の都市人口の割合は増え続け、2000年代後半に5割をこえました。発展途上国では、人口や機能が首都など1つの都市に極端に集中することがあり、その都市を【首位都市(プライメートシティ)】といいます。タイのバンコクなどが例です。',
        key: '都市は交通の結節点に発達。CBD・衛星都市・都市圏・メガロポリス。途上国では首位都市への一極集中。' },
      { h: '都市問題とその対策', t: '都市が急に大きくなると、さまざまな問題が起こります。発展途上国と先進国では、その中身がちがいます。\n【発展途上国】では、農村から仕事を求めて多くの人が都市へ移ってきます(人口の【プッシュ要因】と【プル要因】)。しかし、工業化が追いつかず、安定した仕事や住宅が足りません。そのため、路上での物売りなど、統計にあらわれない仕事(【インフォーマルセクター】)につく人が多く、都市の周辺や空き地などに、上下水道などの設備が整っていない住宅地(【スラム】)が広がります。交通渋滞や大気汚染も深刻です。\n【先進国】では、都市の中心部から郊外へ人口が移ることで、中心部の人口が減る【ドーナツ化現象】が起こりました。大都市の古い市街地では、住民の流出や施設の老朽化が進み、低所得者が取り残されて治安が悪化するなどの【インナーシティ問題】が見られます。また、郊外で無計画に市街地が広がる【スプロール現象】も起こりました。\n対策として、ロンドンでは市街地の拡大をおさえる緑地帯(【グリーンベルト】)を設け、その外側に職場と住宅をあわせもつ【ニュータウン】を建設しました。パリでは、歴史的な景観を守るため、郊外のラ・デファンス地区に高層ビルの並ぶ新しい業務地区をつくりました。\n近年は、古い市街地の再開発で高所得者が移り住み、地価が上がって元の住民が住めなくなる【ジェントリフィケーション】も問題になっています。',
        key: '途上国=スラム・インフォーマルセクター、先進国=ドーナツ化・インナーシティ問題・スプロール。対策はグリーンベルト・ニュータウン・再開発。',
        ex: [{ q: '発展途上国の大都市でスラムが広がるのはなぜ?「農村」「仕事」「住宅」の3語を使って説明しよう。', hint: '人がなぜ都市に来るのか、来た人がどうなるのかを順に考えます。', steps: ['農村では人口が増えて土地や仕事が足りず、人々は現金収入を求めて都市へ移る。', '都市には仕事があると期待されるが、工業化が追いつかず、安定した仕事は足りない。', '収入が少ないため、正式な住宅を借りたり買ったりできない。', 'その結果、空き地や川ぞいなどに簡素な住宅を建てて住む人が増え、スラムが広がる。'], a: '農村から仕事を求めて多くの人が都市に流入するが、安定した仕事や住宅が足りず、設備の整わない住宅地に住む人が増えるから。', check: '都市の人口増加の速さに、工業化(雇用)と住宅・インフラの整備が追いついていない、という点がふくまれているか確かめます。' }] },
      { h: '村落の立地と形態', t: '村落は、生活に欠かせない【水】が得やすい所、洪水や外敵から身を守りやすい所などに立地してきました。扇状地の扇端(わき水)や、氾濫原の自然堤防(洪水に強い)がその例です。\n家屋が密集している村落を【集村】、1戸ずつ離れて散らばっている村落を【散村】といいます。集村は、水の得られる場所がかぎられていたり、共同作業や防御のために集まる必要があったりする所にできます。\n集村には、家屋が不規則に集まった【塊村】、道路に沿って並ぶ【路村】、さらに商店などが並んで町のようになった【街村】、自然堤防や扇端などに沿って家が列状に並ぶ【列村】、広場や教会を囲んで円形に家が並ぶ【円村】などがあります。\n散村は、自分の家のまわりに耕地をまとめられるので、農作業に便利です。富山県の【砺波平野】では、屋敷林に囲まれた家が水田の中に点在しています。アメリカでは、土地を碁盤の目のように区画して開拓者に分けあたえた【タウンシップ制】のもとで、散村が広がりました。\n日本の歴史的な村落には、まわりに堀をめぐらせた奈良盆地などの【環濠集落】、江戸時代に新しく田畑を開いた【新田集落】、明治時代に北海道の開拓と警備のためにつくられた【屯田兵村】などがあります。',
        key: '集村(塊村・路村・街村・列村・円村)と散村(砺波平野・タウンシップ制)。村落は水と安全を求めて立地する。',
        ex: [{ q: '砺波平野の散村で、家どうしが離れて建っているのはなぜ?利点を2つ挙げよう。', hint: '家と耕地の位置関係や、家の周りの林の役割を考えます。', steps: ['散村では、それぞれの家のまわりに自分の耕地(水田)をまとめて持つことができる。', 'そのため、家から田までの移動が短く、農作業に便利である。', '家どうしが離れているので、火事が起きても燃え広がりにくい。', '家を囲む屋敷林は、冬の季節風や夏の日ざしを防ぐ役割もはたしている。'], a: '家のまわりに耕地をまとめられて農作業に便利なこと、家どうしが離れているので火事が燃え広がりにくいこと。', check: '集村と比べて「耕地との距離」がどう変わるかを考えると、散村の利点を説明できているか確かめられます。' }] }
    ],
    faq: [
      ['人口が減ると、悪いことばかりなの?', '働き手の減少や社会保障の負担が大きくなるなどの課題がありますが、通勤ラッシュや住宅不足がやわらぐといった面もあります。\n大切なのは、人口の変化に合わせて、地域の仕組み(交通・医療・行政など)をつくりかえていくことです。'],
      ['人口転換の第2段階で、なぜ出生率より先に死亡率が下がるの?', '医療や衛生の技術は、外国から導入すればすぐに広まり、死亡率を短い期間で下げられます。\n一方、「子どもを何人もつか」という考え方は、教育や社会の仕組み、宗教や習慣と結びついているので、変わるのに時間がかかるからです。'],
      ['都市への人口集中は、なぜ起こるの?', '農村での土地不足や仕事の少なさなど、人を地域から押し出す力(プッシュ要因)と、都市での仕事・教育・医療・便利な生活など、人を引き寄せる力(プル要因)がはたらくからです。']
    ],
    terms: [['エクメーネ', '人が日常的に住んでいる地域'], ['人口転換', '経済の発展とともに、多産多死→多産少死→少産少死と移り変わること'], ['人口爆発', '死亡率の低下などで起こる急激な人口増加'], ['合計特殊出生率', '1人の女性が一生のうちに産む子どもの数の平均'], ['首位都市(プライメートシティ)', '国の人口や機能が極端に集中している都市'], ['メガロポリス', 'いくつもの大都市圏が帯のようにつながった巨大な都市地域'], ['インナーシティ問題', '大都市の古い中心部で、人口流出や老朽化により治安悪化などが起こる問題'], ['散村', '家屋が1戸ずつ離れて散らばっている村落']],
    miss: ['人口爆発の原因を「出生率が上がったから」と考える。実際は医療・衛生の改善で死亡率が下がり、出生率は高いままだったから。', 'つりがね型とつぼ型を混同する。すそ(子どもの部分)が中ほどと同じ幅ならつりがね型、中ほどよりせまければつぼ型と、すその幅を見る。', '高齢化社会・高齢社会・超高齢社会の基準を混同する。7%・14%・21%と、7の倍数で覚える。', '都市の星型と農村のひょうたん型を逆にする。若い世代が「集まって星のようにふくらむ」のが都市、「出て行ってくびれる」のが農村、と人の動きで考える。'],
    sum: ['世界の人口は約80億人。インド・中国・アメリカが多く、アジアに約6割が住む。', '人口転換は多産多死→多産少死(人口爆発)→少産少死。', '人口ピラミッドは富士山型(途上国)・つりがね型(安定)・つぼ型(少子高齢化)。都市は星型、農村はひょうたん型。', '途上国は人口増加とスラム、先進国は少子高齢化とインナーシティ問題が課題。', '村落は水と安全を求めて立地し、集村と散村に分けられる。'],
    next: '次は「世界の諸地域(gg_region)」へ進みましょう。これまで学んだ気候・地形・産業・人口の見方を使って、それぞれの地域の特色をまとめます。'
  };

  var FLOOD = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="外水氾濫と内水氾濫の模式図。川の水が堤防をこえるのが外水氾濫、市街地の下水や水路から水があふれるのが内水氾濫"><path d="M10 100 L55 100 L65 60 L75 60 L85 120 L135 120 L145 60 L155 60 L165 100 L212 100" class="ax"/><path d="M77 70 L143 70 L135 120 L85 120 Z" class="fl"/><path d="M146 62 Q164 44 184 94" class="cv2"/><path d="M180 88 L185 96 L188 86" class="cv2"/><line x1="170" y1="108" x2="212" y2="108" class="dash"/><line x1="204" y1="108" x2="204" y2="90" class="cv"/><path d="M199 95 L204 88 L209 95" class="cv"/><text x="104" y="104">川</text><text x="54" y="52">堤防</text><text x="160" y="40">外水</text><text x="176" y="82">内水</text><text x="10" y="134">外水:川の水が堤防をこえる</text><text x="10" y="147">内水:下水や水路があふれる</text></svg>';

  // ===== 世界の諸地域(地誌) =====
  L.gg_region = {
    goal: '世界の主な地域の特色を、自然・歴史と文化・産業・課題の順に整理して説明でき、地域どうしを比べて共通点とちがいを見つけられるようになる。',
    intro: '旅行のガイドブックを開くと、その国の気候、宗教、料理、名物の産業が順番に紹介されています。これは、地域を理解するための順番として、とても理にかなっています。気候が農業や暮らしを決め、歴史や宗教が文化を決め、その上に今の産業や課題があるからです。このように地域ごとの特色をまとめたものを【地誌】といいます。この単元では、これまでの単元で学んだ見方を使って、世界の諸地域を要点にしぼって整理します。',
    pre: 'ここまでの単元で、地域を見るための道具をそろえてきました。気候区分(Af・BW・Cs・Cfb・Dwなど)、大地形(安定陸塊・古期造山帯・新期造山帯)、農業の形態(混合農業・地中海式農業・プランテーションなど)、工業の立地、人口転換です。\n世界の宗教のうち、信者が多く国や民族をこえて広がっているのは、【キリスト教】(カトリック・プロテスタント・正教会など)、【イスラーム】(イスラム教)、【仏教】です。インドの【ヒンドゥー教】のように、特定の地域や民族と結びついた宗教もあります。\n第二次世界大戦後、アジアやアフリカの多くの国が植民地から独立しました。植民地時代のなごりは、今も言語・宗教・国境・産業(モノカルチャー経済)などに残っています。\n近くの国々が協力して、貿易の障壁をなくしたり、政治的に協力したりする動きを【地域統合】といいます。EU・ASEAN・USMCAなどがその例です。',
    secs: [
      { h: '地誌のまとめ方', t: '地誌をまとめる方法には、大きく2つあります。\n1つは、自然・人口・産業・文化などの項目を順番に並べて、地域を総合的に説明する方法です(【静態地誌】)。全体を見わたすのに向いています。\nもう1つは、その地域を最もよく表すテーマを1つ選び、それを中心にほかの項目を結びつけて説明する方法です(【動態地誌】)。たとえば東南アジアなら「工業化」、アフリカなら「植民地支配の影響」を中心にすると、ばらばらの知識がつながります。\nどちらの方法でも大切なのは、「なぜそうなのか」を前の項目と結びつけることです。「熱帯で高温多雨だから(自然)、油やしのプランテーションが広がり(産業)、森林の減少が問題になっている(課題)」のように、原因と結果でつなぎます。\nこの単元では、それぞれの地域を「自然→歴史・文化→産業→課題」の順に整理します。',
        key: '地誌は「自然→歴史・文化→産業→課題」を、原因と結果でつないで整理する。',
        flow: { title: '世界の諸地域のキーワード', cols: 3, head: ['地域', '自然・文化', '産業・課題'], rows: [
          [['東アジア', 'o'], ['季節風・稲作と畑作', 'o', 1, '漢字・儒教'], ['経済特区・格差', 'o', 1, '少子高齢化']],
          [['東南アジア', 'gr'], ['熱帯・季節風', 'gr', 1, '仏教・イスラーム・キリスト教'], ['ASEAN・工業化', 'gr', 1, 'プランテーション']],
          [['南アジア', 'g'], ['季節風・ガンジス川', 'g', 1, 'ヒンドゥー教'], ['ICT産業・緑の革命', 'g']],
          [['ヨーロッパ', 'b'], ['偏西風・北大西洋海流', 'b', 1, 'キリスト教'], ['EU・混合農業', 'b', 1, '東西の格差']],
          [['アフリカ', 'r'], ['熱帯・乾燥帯', 'r', 1, '植民地の影響'], ['モノカルチャー', 'r', 1, '砂漠化・紛争']],
          [['アメリカ', 'k'], ['新大陸・移民', 'k', 1, 'ヒスパニック'], ['適地適作・サンベルト', 'k', 1, 'USMCA']],
          [['オセアニア', 'p'], ['乾燥大陸・島々', 'p', 1, '多文化主義'], ['鉱産資源・羊', 'p', 1, 'アジアとの結びつき']]
        ] } },
      { h: '東アジア:中国と韓国', t: '【自然】東アジアの東部は、夏に海から湿った季節風がふき、雨が多くなります。中国では、チンリン(秦嶺)山脈とホワイ川(淮河)を結ぶ線が、ほぼ年降水量1000mmの線と一致し、その北は小麦などの【畑作】、南は【稲作】が中心です。西部は乾燥した砂漠や、標高の高いチベット高原が広がります。\n【文化】中国は人口の大部分を【漢族】がしめ、そのほかに50をこえる【少数民族】が暮らしています。漢字や儒教の影響は、朝鮮半島や日本にも広がりました。\n【産業】中国は1979年以降の【改革・開放政策】で、シェンチェン(深圳)などの【経済特区】に外国の資本と技術を受け入れ、急速に工業化しました。現在は世界有数の工業国であり、「世界の工場」から、巨大な消費市場、そして先端技術の開発国へと変わりつつあります。\n【課題】工業化が進んだ沿海部と、農村の多い内陸部の間には大きな【経済格差】があります。政府は2000年から内陸部の開発を進める【西部大開発】を行ってきました。また、一人っ子政策の影響で高齢化が急速に進んでいます。\n【韓国】は1960年代以降に急速に工業化したNIEsの1つで、半導体・自動車・造船などがさかんです。首都ソウルに人口や企業が集中していることや、日本以上に低い出生率が課題です。',
        key: '中国はチンリン山脈・ホワイ川の線の北が畑作、南が稲作。改革・開放と経済特区で工業化、沿海部と内陸部の格差が課題。',
        ex: [{ q: '中国の農業で、北部では小麦などの畑作、南部では稲作が中心になっている理由を説明しよう。', hint: '境目になっている線と、年降水量の関係を考えます。', steps: ['中国の北部と南部の農業の境目は、チンリン山脈とホワイ川を結ぶ線である。', 'この線は、ほぼ年降水量1000mmの線と一致する。', '南部は夏の季節風で高温多雨になり、水を多く必要とする稲作に適している。', '北部は降水量が少なく冬の寒さも厳しいので、乾燥に比較的強い小麦などの畑作が中心になる。'], a: '南部は年降水量が多く高温なので稲作に適し、北部は年降水量が1000mmより少なく寒いため、小麦などの畑作が中心になるから。', check: '同じ東アジアの日本は全体に降水量が多く、稲作がさかんであることと矛盾しないか確かめます。' }] },
      { h: '東南アジア:多様な文化とASEANの工業化', t: '【自然】東南アジアは赤道をはさんで広がり、大部分が熱帯です。半島部は季節風の影響で雨季と乾季があり、島々の多くは1年中雨が多い熱帯雨林気候です。メコン川やチャオプラヤ川などの下流の三角州は、世界有数の稲作地帯です。\n【文化】東南アジアは、インド・中国・イスラーム・ヨーロッパなど、さまざまな地域の影響を受けてきました。タイやミャンマーでは【仏教】、インドネシアやマレーシアでは【イスラーム】、フィリピンでは【キリスト教(カトリック)】の信者が多数をしめます。インドネシアは、世界で最もムスリム(イスラーム教徒)の人口が多い国です。また、中国から移り住んだ人々の子孫である【華人】が、商業などで大きな役割を果たしています。マレーシアでは、マレー系住民を優遇する【ブミプトラ政策】がとられてきました。\n【産業】植民地時代に開かれたプランテーションで、天然ゴム・油やし・コーヒー・バナナなどが栽培されてきました。マレーシアでは天然ゴムから油やしへの転換が進みました。1970年代以降は、税の優遇などで外国企業を呼びこむ【輸出加工区】がつくられ、電気機械や自動車の工業が発達しました。\n【地域統合】1967年に結成された【ASEAN(東南アジア諸国連合)】には、東南アジアのほぼすべての国が加盟し、域内の関税の引き下げなど経済的な協力を進めています。\n【課題】油やし農園の拡大などによる熱帯林の減少や、都市への人口集中、国内の地域格差などがあります。',
        key: 'タイ=仏教、インドネシア・マレーシア=イスラーム、フィリピン=カトリック。ASEANは1967年結成。プランテーションから工業化へ。',
        ex: [{ q: '次の国と、信者の最も多い宗教を正しく組み合わせよう。国:タイ・インドネシア・フィリピン 宗教:イスラーム・仏教・キリスト教(カトリック)', hint: 'それぞれの国に強い影響をあたえた地域や、旧宗主国を考えます。', steps: ['タイは、インドやスリランカから伝わった上座仏教が広まり、国民の大部分が仏教徒である。', 'インドネシアは、13世紀ごろからイスラーム商人との交易を通じてイスラームが広まった。', 'フィリピンは、16世紀から長くスペインの植民地だったため、カトリックが広まった。'], a: 'タイ=仏教、インドネシア=イスラーム、フィリピン=キリスト教(カトリック)', check: 'フィリピンの旧宗主国スペインがカトリックの国であることと、結びつきが合っているか確かめます。' }] },
      { h: '南アジア:インドを中心に', t: '【自然】南アジアは、北に新期造山帯のヒマラヤ山脈、南に安定陸塊のデカン高原があり、その間にガンジス川などの大平原が広がります。夏の季節風(モンスーン)が大量の雨をもたらし、農業に大きな影響をあたえます。\n【文化】インドでは国民の約8割が【ヒンドゥー教】を信仰し、牛を神聖なものとしています。生まれによって職業や結婚などが決まる身分制度【カースト】は憲法で差別が禁止されていますが、慣習として影響が残っています。言語が多く、連邦の公用語はヒンディー語で、英語も広く使われます。パキスタンとバングラデシュはイスラーム、スリランカは仏教の信者が多い国です。\n【農業】降水量によって作物が変わります。雨の多いガンジス川下流域やアッサム地方では稲や【茶】、ジュートが、雨の少ないパンジャブ地方では灌漑による【小麦】が、デカン高原では玄武岩が風化した黒色の土【レグール】を生かした【綿花】がさかんです。1960年代からの【緑の革命】で穀物生産が増え、牛乳の生産を増やした取り組みは【白い革命】とよばれます。\n【工業】英語を話せる理数系の人材が多く、アメリカとの時差(約半日)を利用して仕事を引きつげることなどから、ベンガルールを中心に【ICT産業】が大きく成長しました。自動車工業なども発達しています。\n【課題】人口の多さと増加、都市のスラム、農村と都市の格差などがあります。',
        key: 'インド=ヒンドゥー教(約8割)。稲・茶(多雨地域)、小麦(パンジャブ・灌漑)、綿花(デカン高原・レグール)。ベンガルールのICT産業。',
        ex: [{ q: 'インドの次の地域でさかんな農産物を答えよう。(1)アッサム地方 (2)パンジャブ地方 (3)デカン高原', hint: 'それぞれの地域の降水量と土壌を考えます。', steps: ['アッサム地方は、夏の季節風が山地にぶつかり、世界有数の多雨地域になっている。水はけのよい丘陵で【茶】が栽培される。', 'パンジャブ地方は降水量が比較的少ないが、インダス川の支流などからの灌漑で【小麦】の大産地になっている。', 'デカン高原には、玄武岩が風化してできた黒色の土【レグール】が分布し、【綿花】の栽培に適している。'], a: '(1)茶 (2)小麦 (3)綿花', check: '雨が多いほど茶・稲、少ないほど小麦・綿花という傾向が、ほかの国にも当てはまるか確かめます。' }] },
      { h: 'ヨーロッパ:EUの統合と課題', t: '【自然】ヨーロッパは、暖流の北大西洋海流と偏西風の影響で、高緯度のわりに冬が温和です。西部は西岸海洋性気候、南部は地中海性気候、東部は冷帯が中心です。北部には氷河にけずられたフィヨルドやモレーンが見られます。\n【文化】ヨーロッパの多くの国ではキリスト教が信仰されていますが、宗派と言語の分布には大まかな傾向があります。北西部はゲルマン系の言語とプロテスタント、南部はラテン系の言語とカトリック、東部はスラブ系の言語と正教会が多くなっています。ただし、ポーランドはスラブ系の言語でカトリック、アイルランドはカトリックが多いなど例外もあります。\n【産業】農業では、北西部で混合農業や酪農、地中海沿岸で地中海式農業がさかんです。工業は、イギリス南部からライン川流域を経て北イタリアにいたる【青いバナナ】に集中しています。\n【地域統合】2度の世界大戦への反省と、アメリカやソ連に対抗する経済力をもつため、ヨーロッパは統合を進めてきました。1993年に【EU(ヨーロッパ連合)】が発足し、加盟国の間では人・物・資金・サービスの移動が原則自由になりました。多くの国では共通通貨【ユーロ】が使われ、国境での出入国審査をなくす【シェンゲン協定】も結ばれています。\n【課題】2000年代に東ヨーロッパの国々が多く加盟し、西ヨーロッパとの【経済格差】が大きくなりました。賃金の高い国への労働者の移動や、中東・アフリカからの移民・難民の受け入れをめぐる対立も生まれています。2020年には、イギリスがEUを離脱しました。',
        key: 'EU=1993年発足。人・物・資金・サービスの自由な移動、共通通貨ユーロ。東西の経済格差、移民・難民、イギリスの離脱(2020年)が課題。',
        chain: { title: 'ヨーロッパの統合の歩み', items: [
          ['1952', 'ECSC(ヨーロッパ石炭鉄鋼共同体)', '石炭と鉄鋼を共同で管理'],
          ['1958', 'EEC(ヨーロッパ経済共同体)', '1967年にEC(ヨーロッパ共同体)へ'],
          ['1993', 'EU(ヨーロッパ連合)発足', 'マーストリヒト条約'],
          ['1999', '共通通貨ユーロの導入', '2002年から紙幣・硬貨が流通'],
          ['2020', 'イギリスがEUを離脱', '国民投票(2016年)の結果による']] },
        ex: [{ q: 'EUの統合が進んだことで、加盟国の人々の暮らしにはどんな利点と課題が生まれた?1つずつ挙げよう。', hint: '国境をこえた移動が自由になったことから考えます。', steps: ['加盟国の間では人・物・資金・サービスの移動が原則自由になった。', '利点:ほかの加盟国で自由に働いたり学んだりでき、ユーロを使う国の間では両替なしで買い物や旅行ができる。', '課題:賃金の低い国から高い国へ働き手が移り、送り出す国では人材が流出し、受け入れる国では仕事の競争や社会保障の負担をめぐる不満が生まれた。'], a: '利点:国境をこえて自由に働いたり旅行したりでき、ユーロを使う国の間では両替がいらない。課題:加盟国の間の経済格差から労働者が移動し、人材の流出や受け入れをめぐる対立が生まれた。', check: 'イギリスのEU離脱の議論で、移民の受け入れが大きな争点になったことと結びついているか確かめます。' }] },
      { h: 'アフリカ・西アジア:乾燥と資源、植民地の影響', t: '【自然】アフリカは大部分が安定陸塊の高原で、赤道付近に熱帯雨林、その南北にサバナ、さらに南北の回帰線付近にサハラ砂漠やカラハリ砂漠などの乾燥帯が広がります。東部には広がる境界である【アフリカ大地溝帯】があります。\n【歴史】19世紀末までに、アフリカのほとんどの地域がヨーロッパ諸国の植民地にされました。そのとき、民族の分布を無視して経線や緯線にそって境界が引かれたため、今も直線的な国境が多く見られます。1960年は多くの国が独立したため「アフリカの年」とよばれます。独立後、1つの国の中に多くの民族がいることなどから、内戦や紛争が起きた地域もあります。\n【産業】植民地時代の名残で、カカオ(コートジボワール・ガーナ)のような特定の農産物や、石油・銅・金・ダイヤモンドなど特定の鉱産資源の輸出にたよる【モノカルチャー経済】の国が多く、国際価格の変動で経済が不安定になりやすい課題があります。南アフリカ共和国は工業化が進んだ国ですが、かつての人種隔離政策【アパルトヘイト】(1991年に関連法を廃止)の影響で、経済格差が残っています。\n【課題】サハラ砂漠の南の【サヘル】では、干ばつに加えて、人口の増加による過放牧・過耕作・薪の採りすぎなどで【砂漠化】が進んでいます。2002年には、アフリカの国々の協力を進める【AU(アフリカ連合)】が発足しました。\n【西アジア】は乾燥帯が中心で、イスラームの信者が多い地域です。ペルシア湾岸は世界最大の石油の産地で、石油の収入をもとに都市開発が進んだ国もあります。',
        key: 'アフリカ=植民地支配の名残(直線的な国境・モノカルチャー経済)。サヘルの砂漠化。AU(2002年)。西アジア=乾燥・イスラーム・石油。',
        ex: [{ q: 'アフリカの多くの国で、経済がモノカルチャーになりやすく、不安定になりやすいのはなぜ?', hint: '植民地時代に、何のために開発が行われたかを考えます。', steps: ['植民地時代、アフリカでは宗主国が必要とする特定の農産物や鉱産資源を生産する開発が進められた。', '独立後もその仕組みが残り、輸出の大部分を少数の品目にたよる国が多くなった。', 'その品目の国際価格が下がったり、不作になったりすると、国の収入が大きく減る。', '工業化や産業の多角化に必要な資金や技術が不足していることも、仕組みを変えにくくしている。'], a: '植民地時代に特定の作物や鉱産資源を輸出する仕組みがつくられ、独立後もそれにたよっているため、国際価格の変動で国の収入が大きく変わるから。', check: 'カカオにたよるコートジボワールやガーナの経済が、カカオ価格の上下で左右されることと合っているか確かめます。' }] },
      { h: 'アメリカとオセアニア:移民がつくった社会', t: '【アングロアメリカ】アメリカ合衆国は、ヨーロッパやアフリカ、アジア、ラテンアメリカから来た人々がつくった多民族の国です。近年は、メキシコなどラテンアメリカからのスペイン語を話す移民(【ヒスパニック】)が増えています。農業は、気候や土壌に合わせて作物を選ぶ【適地適作】が特徴で、五大湖周辺の酪農、中西部のとうもろこしや大豆(【コーンベルト】)、グレートプレーンズの小麦、南部の綿花などが分布します。カナダは英語とフランス語が公用語で、ケベック州ではフランス語を話す人が多数です。2020年には、アメリカ・メキシコ・カナダの間で【USMCA】が発効しました。\n【ラテンアメリカ】メキシコ以南の地域は、スペインやポルトガルの植民地だった歴史から、多くの国でスペイン語が、ブラジルではポルトガル語が話され、カトリックの信者が多くなっています。先住民と白人の混血の人々(【メスチーソ】)が多い国もあります。少数の地主が広大な農地をもつ【大土地所有制】が残り、貧富の差が課題です。ブラジルでは、さとうきびからつくる【バイオエタノール】が自動車の燃料に使われています。アマゾンの開発による熱帯林の減少も問題です。\n【オセアニア】オーストラリアは、大陸の大部分が乾燥帯で、人口は南東部の沿岸に集中しています。羊や牛の放牧、小麦の栽培がさかんで、北西部の鉄鉱石、東部の石炭など鉱産資源も豊富です。かつてはヨーロッパ系以外の移民を制限する【白豪主義】をとっていましたが、1970年代にやめ、さまざまな文化を尊重する【多文化主義】へ転換しました。先住民アボリジニーの権利の回復も進められています。貿易相手は、かつてのイギリス中心から、中国や日本などアジアの国々が中心になりました。ニュージーランドでは、先住民マオリの文化が尊重され、羊の飼育や酪農がさかんです。',
        key: 'アメリカ=適地適作・ヒスパニック・USMCA。ラテンアメリカ=スペイン語(ブラジルはポルトガル語)・大土地所有制。オーストラリア=白豪主義から多文化主義へ、アジアとの結びつき。',
        ex: [{ q: 'オーストラリアの主な貿易相手が、イギリスからアジアの国々へ変わったのはなぜ?', hint: '歴史的な結びつきと、地理的な近さ・経済の成長を比べます。', steps: ['オーストラリアはイギリスの植民地だったので、かつてはイギリスとの貿易が中心だった。', '1973年にイギリスがEC(現在のEU)に加盟し、ヨーロッパの国々との結びつきを強めた。', '一方、地理的に近いアジアでは、日本や中国などが経済成長し、鉄鉱石・石炭などの資源や農産物の大きな買い手になった。', 'さらに白豪主義の撤廃でアジアからの移民も増え、アジアとの結びつきが強まった。'], a: 'イギリスがECに加盟してヨーロッパとの結びつきを強めた一方、近くのアジアの国々が経済成長して、オーストラリアの資源や農産物の大きな買い手になったから。', check: 'オーストラリアの主な輸出品が鉄鉱石・石炭など資源であり、それを多く輸入しているのが中国や日本であることと合っているか確かめます。' }] }
    ],
    faq: [
      ['地誌の問題は、全部の国を覚えないといけないの?', 'すべてを丸暗記する必要はありません。まず気候区分と大地形の分布を地図で押さえ、そこから農業や生活を説明できるようにすると、多くの国に応用できます。\nそのうえで、各地域の代表的な国(中国・インド・アメリカ・ブラジル・オーストラリアなど)の特色をしっかり覚えましょう。'],
      ['ASEANとEUはどうちがうの?', 'EUは、共通通貨ユーロや共通の議会をもつなど、国の権限の一部を共同で行使する深い統合をしています。\nASEANは、それぞれの国の主権を尊重しながら、経済や安全保障の面で協力することを中心にしています。'],
      ['ヒスパニックとメスチーソはどうちがうの?', 'ヒスパニックは、アメリカ合衆国で、スペイン語を話すラテンアメリカ系の人々をまとめてよぶことばです。\nメスチーソは、ラテンアメリカで、先住民と白人(ヨーロッパ系)の混血の人々をさすことばです。使われる場所と意味がちがいます。']
    ],
    terms: [['地誌', '地域ごとに、自然・文化・産業などの特色をまとめたもの'], ['経済特区', '中国が外国の資本や技術を受け入れるために設けた地区'], ['ASEAN', '1967年に結成された東南アジア諸国連合'], ['華人', '中国から移り住んだ人々とその子孫'], ['カースト', 'インドの、生まれによって職業などが決まる身分制度'], ['EU', '1993年に発足したヨーロッパ連合'], ['モノカルチャー経済', '特定の農産物や鉱産資源の輸出にたよる経済'], ['多文化主義', 'さまざまな民族の文化を尊重し、共生をめざす考え方']],
    miss: ['ブラジルの言語をスペイン語と答える。ブラジルはポルトガルの植民地だったのでポルトガル語、と旧宗主国から考える。', 'インドネシアやマレーシアを仏教の国と考える。イスラーム商人との交易で広まったイスラームが中心で、仏教の信者が多いのはタイやミャンマー。', 'EUの加盟国はすべてユーロを使っていると考える。ユーロを導入していない加盟国もある。', 'アフリカの直線的な国境を、自然の地形にそったものと考える。植民地時代にヨーロッパ諸国が経緯線などを使って引いた境界であることが多い。'],
    sum: ['地誌は「自然→歴史・文化→産業→課題」を原因と結果でつないで整理する。', '中国は改革・開放と経済特区で工業化し、沿海部と内陸部の格差が課題。', '東南アジアは宗教が多様で、ASEANのもとで工業化が進んだ。インドはヒンドゥー教とICT産業。', 'EUは人・物・資金・サービスの移動を自由にしたが、東西の格差や移民をめぐる課題がある。', 'アフリカは植民地支配の影響が残り、アメリカは移民と適地適作、オーストラリアは多文化主義とアジアとの結びつきが特色。'],
    next: '最後は「自然災害と防災・持続可能な地域づくり(gg_disaster)」へ進みましょう。地形や気候の知識を、身近な地域の安全と未来を考えることに生かします。'
  };

  // ===== 自然災害と防災・持続可能な地域づくり =====
  L.gg_disaster = {
    goal: '日本と世界の自然災害のしくみを地形・気候と結びつけて説明でき、ハザードマップなどを使って防災・減災の方法を考え、地球環境問題と持続可能な地域づくりについて説明できるようになる。',
    intro: '同じ大雨が降っても、ある町では何も起こらず、別の町では家が水につかります。同じ地震でも、ある場所では大きな被害が出て、別の場所ではほとんど被害がありません。このちがいは、どこから生まれるのでしょうか。【自然災害】は、大雨や地震などの自然の力(自然現象)そのものではなく、それが人の住む場所や社会の弱さと重なったときに起こるものです。この単元では、災害が起こるしくみを地形や気候から理解し、被害を減らすための方法を考えます。',
    pre: '前の単元までに学んだ地形の知識は、防災にそのまま使えます。扇状地、氾濫原の自然堤防と後背湿地、三角州、リアス海岸などは、それぞれ起こりやすい災害がちがいます。\n日本列島は、海洋プレートが大陸側のプレートの下にしずみこむ【せばまる境界】にあり、地震や火山活動が活発です。\nまた、日本は夏から秋にかけて【台風】や梅雨前線による大雨が多く、冬には日本海側で大雪が降ります。山が多く川が短く急流なので、大雨が降ると水が一気に流れ下ります。\n地形図の等高線や地図記号を読む力も必要です。国土地理院の地理院地図では、地形図に土地の成り立ちや標高などを重ねて見ることができます。',
    secs: [
      { h: '自然災害はどのように起こるか', t: 'なぜ同じ自然現象でも、被害の大きさがちがうのでしょうか。被害は、自然の力の大きさ(危険の大きさ)と、そこに住む人や建物、社会のしくみの【弱さ】(ぜい弱性)の組み合わせで決まるからです。\nたとえば、無人の山で地すべりが起きても被害はありませんが、同じ場所に住宅地があれば災害になります。また、耐震化された建物の多い地域と、古い建物が多い地域では、同じ揺れでも被害が大きく変わります。\n自然災害には、地震・津波・火山噴火のように地球内部の力によるものと、台風・豪雨・豪雪・干ばつなど気象によるものがあります。\n日本は、世界で起こるマグニチュード6以上の地震の約2割が周辺で発生し、100をこえる活火山があるなど、世界でも自然災害の多い国です。\n世界に目を向けると、低くて人口の多いバングラデシュのサイクロンによる高潮、サヘルの干ばつ、環太平洋造山帯の地震や火山など、地域の地形や気候に応じた災害があります。発展途上国では、防災の設備や情報が不足しているため、被害が大きくなりやすい傾向があります。',
        key: '災害の被害=自然の力の大きさ×社会の弱さ。弱さを小さくすれば被害を減らせる。' },
      { h: '地震と津波', t: '地震には大きく2つのタイプがあります。\n【海溝型地震】は、海洋プレートがしずみこむ海溝付近で、陸側のプレートがはね上がって起こる地震です。規模が大きく、津波をともなうことが多いのが特徴です。2011年の東北地方太平洋沖地震(マグニチュード9.0)による東日本大震災では、巨大な津波が東北地方の太平洋岸などをおそいました。今後、南海トラフでの巨大地震も心配されています。\n【内陸型地震】(直下型地震)は、陸のプレートの内部にある【活断層】がずれて起こる地震です。震源が浅く、人の住む場所の真下で起こると激しい揺れになります。1995年の兵庫県南部地震(阪神・淡路大震災)では、建物の倒壊や火災で大きな被害が出ました。\n地震の揺れによって、埋め立て地や昔の川の跡(旧河道)など、砂が多く地下水位の高い土地では、地盤が液体のようになる【液状化現象】が起こります。建物がかたむいたり、マンホールが浮き上がったりします。\n【津波】は、海底が急にもち上がったりしずんだりして海水全体が動くことで起こります。海が深い所ほど速く進み、陸に近づいて浅くなると速さが落ちる代わりに波が高くなります。リアス海岸のV字形の湾の奥では、特に高くなりやすくなります。「揺れたらすぐに高い所へ逃げる」ことが最も大切です。',
        key: '海溝型地震=規模が大きく津波をともなう。内陸型地震=活断層、浅く激しい揺れ。液状化は埋め立て地・旧河道に注意。',
        ex: [
          { q: '津波の速さは、およそ √(9.8×水深) [m/s] で表される。水深4000mの海で、津波の速さはおよそ何km/h?', hint: 'まず√の中を計算し、m/sをkm/hに直すには3.6をかけます。', steps: ['9.8×4000=39200。', '√39200 はおよそ198(198×198=39204)なので、速さは約198m/s。', 'km/hに直すと、198×3.6≒713km/h。'], a: '約700km/h(ジェット機に近い速さ)', check: '水深が4分の1の1000mなら速さは半分(約99m/s)になるので、浅くなるほど遅くなるという説明と一致します。' },
          { q: '同じ市内で、台地の上の住宅地と、海を埋め立てた住宅地がある。大地震のとき液状化現象の危険が高いのはどちら?理由も答えよう。', hint: '液状化が起きやすい土地の条件は、「砂が多い」「地下水位が高い」です。', steps: ['液状化は、砂でできた地盤の中に水が多くふくまれているときに、揺れで砂の粒どうしのかみ合わせが外れて起こる。', '埋め立て地は、海に砂や土を入れてつくった新しい土地で、地盤がやわらかく、地下水位も高い。', '台地は古くからある比較的かたい地盤で、地下水位も低い。'], a: '埋め立て地。砂の多いやわらかい地盤で地下水位が高く、揺れで地盤が液体のようになりやすいから。', check: '東日本大震災のとき、東京湾岸の埋め立て地で広い範囲に液状化が起きたことと合っているか確かめます。' }
        ] },
      { h: '火山の災害と恵み', t: '日本の火山の多くは、プレートのしずみこみにともなってできたマグマが地表に出てきたものです。火山は災害をもたらす一方で、大きな恵みもあたえてくれます。\n【災害】溶岩の流出のほか、高温の火山ガスや火山灰・岩石が高速で斜面を流れ下る【火砕流】は特に危険です。1991年には長崎県の雲仙普賢岳で火砕流による大きな被害が出ました。噴火口の近くでは大きな岩が飛ぶ噴石、広い範囲では火山灰による農作物や交通への被害、火山灰が雨で流される泥流なども起こります。\n【恵み】火山の熱は、温泉や【地熱発電】に利用されます。火山がつくった湖やカルデラ(噴火でできた大きなくぼ地。阿蘇山など)、美しい山の景観は観光資源になります。火山灰からできた土地は、作物の栽培に工夫が必要ですが、畑作や畜産に利用されています。\n火山の防災では、気象庁が火山の活動状況に応じて【噴火警戒レベル】を発表し、立ち入りを規制したり避難をよびかけたりします。また、多くの火山で火山ハザードマップがつくられています。',
        key: '火山は火砕流・噴石・火山灰などの災害と、温泉・地熱・景観などの恵みの両面をもつ。' },
      { h: '気象災害:洪水・土砂災害・高潮', t: '日本では、梅雨前線や台風による大雨で多くの気象災害が起こります。近年は、発達した積乱雲が次々に同じ場所を通過する【線状降水帯】による集中豪雨も増えています。\n【洪水】には2つの種類があります。川の水が増えて堤防をこえたり、堤防がこわれたりしてあふれるのが【外水氾濫】です。これに対して、大雨で下水道や水路が雨水を流しきれず、堤防の内側(市街地側)で水があふれるのが【内水氾濫】です。都市では、地面がアスファルトなどでおおわれて雨水が地下にしみこみにくいため、内水氾濫が起こりやすくなっています。\n【土砂災害】には、山の斜面の土砂が雨水とともに一気に流れ下る【土石流】、急な斜面がくずれる【がけ崩れ】、斜面の土地がゆっくりとすべり動く【地すべり】があります。扇状地は、過去の土石流などで運ばれた土砂でできた地形なので、上流で大雨が降ると土石流の危険があります。\n【高潮】は、台風の接近で気圧が下がって海面が吸い上げられ、さらに強い風で海水が海岸に吹き寄せられて、潮位が大きく上がる現象です。三角州や海抜0m地帯(海面より低い土地)では、大きな被害が出るおそれがあります。\nこのほか、日本海側の豪雪による雪害、夏の熱中症を引き起こす猛暑、雨の少ない年の干ばつなどもあります。',
        key: '外水氾濫=川の水が堤防をこえる、内水氾濫=市街地の下水・水路があふれる。土砂災害は土石流・がけ崩れ・地すべり。高潮は気圧の低下と強風。',
        fig: FLOOD },
      { h: '防災と減災:ハザードマップと避難', t: '自然災害を完全に防ぐことはできません。そこで、被害をできるだけ小さくしようという【減災】の考え方が大切になっています。\n対策には、堤防・防潮堤・砂防ダム・遊水地などの施設をつくる【ハード対策】と、ハザードマップ・避難訓練・防災教育・情報の伝達などの【ソフト対策】があります。ハード対策には限界があるので、両方を組み合わせることが必要です。\n【ハザードマップ】は、洪水・土砂災害・津波・高潮などで被害が想定される区域や、避難場所・避難経路などを示した地図です。自分の住む場所の危険を知り、どこへどう逃げるかを前もって決めておくのに役立ちます。土地の成り立ち(旧河道・後背湿地・埋め立て地など)を示した地図や、過去の災害を伝える【自然災害伝承碑】(2019年に地図記号ができた)も、土地の危険を知る手がかりになります。\n大雨のときなどには、住民がとるべき行動を5段階で示す【警戒レベル】が使われます。警戒レベル4の【避難指示】が出たら、危険な場所にいる人は全員避難します。\n防災の担い手は3つに分けられます。自分や家族の命を自分で守る【自助】(家具の固定、備蓄、避難経路の確認など)、地域や近所の人どうしで助け合う【共助】(自主防災組織、高齢者の避難の手助けなど)、国や自治体による【公助】(堤防の整備、避難所の運営、救助など)です。大きな災害では公助が届くまで時間がかかるので、自助と共助がとても重要です。',
        key: '減災=ハード対策+ソフト対策。ハザードマップで危険を知る。警戒レベル4(避難指示)で全員避難。自助・共助・公助。',
        flow: { title: '大雨のときの警戒レベル(住民がとる行動)', cols: 2, rows: [
          [['レベル5:緊急安全確保', 'rr'], ['すでに災害が起きている可能性。命を守る行動を', 'rr']],
          [['レベル4:避難指示', 'r'], ['危険な場所から全員避難', 'r']],
          [['レベル3:高齢者等避難', 'o'], ['高齢者など避難に時間がかかる人は避難', 'o']],
          [['レベル2:大雨・洪水注意報など', 'y'], ['避難場所や避難経路を確認', 'y']],
          [['レベル1:早期注意情報', 'k'], ['災害への心構えを高める', 'k']]
        ], legend: [['r', 'レベル4までに必ず避難']] },
        ex: [
          { q: '次の行動は、自助・共助・公助のどれにあたる?(1)自宅の家具を壁に固定する (2)町内会で、ひとり暮らしの高齢者の避難を手伝う計画をつくる (3)市が避難所を開設し、食料を配る', hint: 'だれが行う行動かを考えます。', steps: ['(1)は自分や家族の命を自分たちで守る行動なので自助。', '(2)は地域の住民どうしが助け合う行動なので共助。', '(3)は自治体(行政)が行う支援なので公助。'], a: '(1)自助 (2)共助 (3)公助', check: '「自分・家族」「地域の人どうし」「国や自治体」と、行う主体で分けられているか確かめます。' },
          { q: 'ハザードマップを見ると、自宅は川に近い後背湿地にあり、浸水の深さが2〜3mと想定されていた。近くの避難所は、川ぞいの自然堤防の上にある学校と、少し遠い台地の上の公民館の2つ。大雨で洪水のおそれがあるとき、どのように避難を考えるとよい?', hint: '浸水の深さと、避難する場所・経路の安全を考えます。', steps: ['自宅は低い後背湿地にあり、2〜3mの浸水は1階がほぼつかる深さなので、早めに家の外へ避難する必要がある。', '避難所が洪水の災害に対応しているか(浸水想定区域の外か)をハザードマップで確かめる。', '川ぞいの学校は堤防がこわれたときに危険が大きいこともあるので、より安全な台地の上の公民館を候補にする。', '避難経路が浸水しやすい低い道を通らないかを確かめ、警戒レベル3〜4の段階で明るいうちに早めに出発する。'], a: '浸水が深いので早めに家から避難する。洪水に対応した、より高く安全な台地の上の公民館を選び、浸水しにくい経路で、警戒レベル4(避難指示)までに避難する。', check: '「どの災害で」「どこへ」「どの道で」「いつ」の4つを決められているかを確かめます。' }
        ] },
      { h: '地球環境問題', t: '災害や環境の問題は、国境をこえて広がることがあります。地球規模で取り組む必要がある主な問題を確認しましょう。\n【地球温暖化】:石炭や石油などの化石燃料を大量に燃やすことで、二酸化炭素などの【温室効果ガス】が増え、地球の平均気温が上がっています。海面の上昇によって、ツバルなど標高の低い島国では国土が失われるおそれがあります。異常気象の増加や、生態系・農業への影響も心配されています。国際的には、1997年の【京都議定書】で先進国に削減目標が定められ、2015年の【パリ協定】では、すべての国が削減目標を出して取り組むことになりました。\n【砂漠化】:サヘルなどの乾燥地域の周辺では、干ばつに加えて、過放牧・過耕作・薪の採りすぎなど人間の活動によって土地がやせ、砂漠のようになっています。\n【熱帯林の減少】:アマゾンや東南アジアなどでは、農地や牧場の開発、油やし農園の拡大、木材の伐採で熱帯林が減っています。熱帯林は多くの生物のすみかであり、二酸化炭素を吸収する役割もあります。\n【酸性雨】:工場や自動車から出る硫黄酸化物や窒素酸化物が雨にとけて酸性の雨となり、森林を枯らしたり湖の生物に影響したりします。風に運ばれて国境をこえる【越境汚染】が問題になります。\n【オゾン層の破壊】:冷蔵庫やスプレーに使われたフロンがオゾン層を破壊し、有害な紫外線が増えました。1987年のモントリオール議定書でフロンの規制が進められています。',
        key: '温暖化(パリ協定2015年)、砂漠化(サヘル)、熱帯林の減少、酸性雨(越境汚染)、オゾン層の破壊(フロン)。地球規模の協力が必要。',
        chain: { title: '地球温暖化の原因と影響', items: [
          ['原因', '化石燃料の大量消費・森林の減少', '二酸化炭素などの温室効果ガスが増える'],
          ['現象', '地球の平均気温が上昇', '氷河がとけ、海水が膨張する'],
          ['影響', '海面上昇・異常気象の増加', '低い島国の水没・豪雨や干ばつ'],
          ['対策', '温室効果ガスの削減・再生可能エネルギー', '京都議定書(1997年)・パリ協定(2015年)']] },
        ex: [{ q: '地球温暖化が進むと、南太平洋のツバルのような島国が特に大きな影響を受けるのはなぜ?', hint: '島の標高と、温暖化で起こる現象を結びつけます。', steps: ['地球温暖化が進むと、陸上の氷河がとけて海に流れこみ、海水も温まって膨張するため、海面が上がる。', 'ツバルなどの島は、サンゴ礁でできた標高の低い島で、最も高い所でも数m程度しかない。', 'そのため、海面のわずかな上昇でも、高潮の被害や土地の浸食、地下水の塩水化が起こりやすい。', '島国では移り住む土地もかぎられるので、国の存続にかかわる問題になる。'], a: '標高の低いサンゴ礁の島で、温暖化による海面上昇の影響で高潮・浸食・地下水の塩水化などが起こりやすく、国土そのものが失われるおそれがあるから。', check: '温暖化の原因(温室効果ガス)をあまり出していない国が大きな被害を受けるという、不公平さの問題にも気づけているか確かめます。' }] },
      { h: '持続可能な地域づくり', t: '【持続可能な開発】とは、将来の世代の暮らしを損なわずに、今の世代の必要を満たす開発のことです。2015年に国連で採択された【SDGs(持続可能な開発目標)】は、貧困・飢餓・教育・ジェンダー・気候変動・まちづくりなど17の目標を、2030年までに達成することをめざしています。\n日本の地域づくりでは、まず人口の変化への対応が課題です。地方では人口の流出と高齢化で【過疎】が進み、交通・医療・商店などの維持が難しくなっている地域があります。\nそこで、住宅や病院・商店・役所などを中心部や駅の近くに集め、公共交通で結ぶ【コンパクトシティ】の取り組みが進められています。富山市では、路面電車(LRT)を中心にしたまちづくりが行われています。移動の負担や行政の費用をおさえ、自動車にたよりすぎない暮らしをめざすものです。\nほかにも、地域でとれた農産物をその地域で消費する【地産地消】、地域の自然や文化を守りながら観光に生かす【エコツーリズム】、地域の太陽光・風力・バイオマスなどを使った再生可能エネルギーの導入などがあります。\n防災も、持続可能な地域づくりの大切な柱です。災害の危険が高い場所をさけて住む、避難しやすいまちの形にする、地域で助け合うしくみをつくる、といった工夫は、人口が減る時代のまちづくりともつながっています。',
        key: 'SDGs(2015年採択・17の目標・2030年まで)。過疎への対応としてのコンパクトシティ、地産地消、エコツーリズム、防災を組みこんだまちづくり。',
        ex: [{ q: '人口が減少している地方都市が、コンパクトシティをめざす理由を2つ挙げよう。', hint: '人口が減ったまま市街地が広く散らばっていると、何が困るでしょうか。', steps: ['人口が減ったのに市街地が広いままだと、道路・上下水道などの施設を維持する費用が1人あたりで大きくなる。', '住む人がまばらだと、バスなどの公共交通の利用者が減り、路線を維持できなくなる。', '住宅や施設を中心部に集めれば、施設の維持費をおさえ、公共交通も利用されやすくなる。', '自動車を運転できない高齢者も、徒歩や公共交通で病院や商店に行けるようになる。'], a: '道路や上下水道などの維持にかかる行政の費用をおさえられること、公共交通を維持して自動車を使えない高齢者も暮らしやすくなること。', check: '中心部に集めることで、災害の危険が高い場所に住む人を減らすことにも役立つかを考えると、防災とのつながりも確かめられます。' }] }
    ],
    faq: [
      ['ハザードマップで色がぬられていない場所は、絶対に安全なの?', '絶対に安全とはいえません。ハザードマップは、ある規模の雨や地震を想定してつくられたもので、それをこえる災害が起こることもあります。\nまた、小さな川や水路の氾濫、内水氾濫などがのっていない場合もあります。色がない場所でも、土地の低さや周りの地形を確かめ、早めに避難することが大切です。'],
      ['なぜ「防災」だけでなく「減災」という考え方が必要なの?', '大きな津波が防潮堤をこえた東日本大震災のように、施設だけで災害を完全に防ぐことはできないからです。\n被害がゼロにならないことを前提に、早めの避難や地域の助け合いで、命や暮らしへの被害をできるだけ小さくする考え方が減災です。'],
      ['地球温暖化と自然災害には関係があるの?', '温暖化によって大気中の水蒸気が増え、強い雨が降りやすくなると考えられています。\n海面上昇は高潮の被害を大きくするおそれもあります。温暖化対策は、将来の災害を減らすことにもつながっています。']
    ],
    terms: [['減災', '災害を完全に防げないことを前提に、被害をできるだけ小さくする考え方'], ['ハザードマップ', '災害の危険がある区域や避難場所などを示した地図'], ['液状化現象', '地震の揺れで、砂の多い地盤が液体のようになる現象'], ['活断層', '最近の地質時代にくり返し活動し、今後も活動するおそれのある断層'], ['内水氾濫', '大雨で下水道や水路があふれ、堤防の内側の市街地が浸水すること'], ['高潮', '台風などの気圧低下と強風で、潮位が大きく上がる現象'], ['自助・共助・公助', '自分で守る・地域で助け合う・国や自治体が支える、の3つの防災の担い手'], ['コンパクトシティ', '住宅や施設を中心部に集め、公共交通で結ぶ都市づくり']],
    miss: ['津波と高潮を混同する。津波は地震などで海底が動いて起こり、高潮は台風の気圧低下と強風で起こる、と原因で区別する。', '外水氾濫と内水氾濫を逆に覚える。「外」=川(堤防の外側の水)があふれる、「内」=市街地の内側の下水や水路があふれる、と堤防を基準に考える。', 'ハザードマップで色がない場所を絶対に安全だと考える。想定をこえる災害や、地図にのっていない危険もあると考え、早めに行動する。', '防災は行政(公助)がやるものだと考える。大災害では公助が届くまで時間がかかるので、自助・共助が命を守る中心になる。'],
    sum: ['自然災害は、自然の力と社会の弱さが重なって起こる。', '海溝型地震は規模が大きく津波をともない、内陸型地震は活断層で起こる。埋め立て地や旧河道は液状化に注意。', '洪水には外水氾濫と内水氾濫がある。土砂災害は土石流・がけ崩れ・地すべり、高潮は気圧の低下と強風で起こる。', 'ハザードマップで危険を知り、警戒レベル4(避難指示)までに避難する。自助・共助・公助を組み合わせて減災をめざす。', '地球環境問題やSDGsを意識し、コンパクトシティや地産地消など持続可能な地域づくりを考える。'],
    next: 'これで地理総合・地理探究の8単元はひととおり終わりです。最初の「地図の図法・時差・GIS(gg_map)」にもどって、GISやハザードマップを使った地域調査の視点で全体を復習しましょう。'
  };
})(WPS.LESSONS);
